BEGIN;
-- UNAPPLIED / NATIVE UNQUALIFIED. No runtime default, signer or delivery.
-- The public plan is an input to validation, never a source of database facts.
CREATE TABLE bootstrap_v3_operations (
 id UUID PRIMARY KEY,workspace_id UUID NOT NULL REFERENCES workspaces(id) ON DELETE RESTRICT,
 attachment_id UUID NOT NULL UNIQUE REFERENCES bootstrap_proof_attachments(id) ON DELETE RESTRICT,
 writer_xid TEXT NOT NULL UNIQUE CHECK(writer_xid~'^[1-9][0-9]*$'),
 plan JSONB NOT NULL,plan_digest TEXT NOT NULL CHECK(plan_digest~'^[a-f0-9]{64}$'),
 anchor JSONB NOT NULL,from_fence BIGINT NOT NULL CHECK(from_fence>0)
);
CREATE TABLE bootstrap_v3_phases (
 operation_id UUID NOT NULL REFERENCES bootstrap_v3_operations(id) ON DELETE RESTRICT,
 ordinal INT NOT NULL CHECK(ordinal BETWEEN 1 AND 6),phase TEXT NOT NULL,
 frame JSONB NOT NULL,PRIMARY KEY(operation_id,ordinal),UNIQUE(operation_id,phase),
 CHECK(phase=(ARRAY['reservation','ticket','channel','attempt','link','seal'])[ordinal])
);
CREATE TABLE bootstrap_v3_seals (
 attempt_id UUID PRIMARY KEY REFERENCES worker_bootstrap_attempts(id) ON DELETE RESTRICT,
 operation_id UUID NOT NULL UNIQUE REFERENCES bootstrap_v3_operations(id) ON DELETE RESTRICT,
 workspace_id UUID NOT NULL REFERENCES workspaces(id) ON DELETE RESTRICT,record JSONB NOT NULL
);
CREATE TABLE bootstrap_v3_seal_audit (
 id UUID PRIMARY KEY,operation_id UUID NOT NULL UNIQUE REFERENCES bootstrap_v3_operations(id) ON DELETE RESTRICT,
 workspace_id UUID NOT NULL REFERENCES workspaces(id) ON DELETE RESTRICT,
 attempt_id UUID NOT NULL UNIQUE REFERENCES bootstrap_v3_seals(attempt_id) ON DELETE RESTRICT,record JSONB NOT NULL
);
CREATE TABLE bootstrap_v3_mutations (
 sequence BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
 operation_id UUID REFERENCES bootstrap_v3_operations(id) ON DELETE RESTRICT,
 writer_xid TEXT NOT NULL,epoch BIGINT NOT NULL,table_name TEXT NOT NULL,row_key TEXT NOT NULL,
 before_digest TEXT,after_digest TEXT,record JSONB,
 CHECK(before_digest IS NOT NULL OR after_digest IS NOT NULL)
);
CREATE TABLE bootstrap_v3_receipts (
 id UUID PRIMARY KEY,operation_id UUID NOT NULL REFERENCES bootstrap_v3_operations(id) ON DELETE RESTRICT,
 mutation_sequence BIGINT NOT NULL REFERENCES bootstrap_v3_mutations(sequence) ON DELETE RESTRICT,
 family TEXT NOT NULL CHECK(family IN ('lifecycle','attestation','transport','proof','projection')),
 event_id UUID NOT NULL UNIQUE REFERENCES events(id) ON DELETE RESTRICT,
 native_table TEXT NOT NULL,native_key TEXT NOT NULL,native_digest TEXT NOT NULL,
 record JSONB NOT NULL,UNIQUE(mutation_sequence,family)
);
CREATE TABLE bootstrap_v3_epoch_claims (
 revision BIGINT PRIMARY KEY,operation_id UUID NOT NULL REFERENCES bootstrap_v3_operations(id) ON DELETE RESTRICT,
 writer_xid TEXT NOT NULL,slot TEXT NOT NULL,guard TEXT NOT NULL CHECK(guard IN ('row_guard','statement_guard','nested_guard')),
 UNIQUE(operation_id,slot,guard)
);
CREATE TABLE bootstrap_v3_epochs (
 revision BIGINT PRIMARY KEY,writer_xid TEXT NOT NULL,
 operation_id UUID REFERENCES bootstrap_v3_operations(id) ON DELETE RESTRICT,
 slot TEXT,guard TEXT,event_id UUID NOT NULL UNIQUE REFERENCES events(id) ON DELETE RESTRICT,
 previous_revision BIGINT NOT NULL,CHECK(revision=previous_revision+1)
);
CREATE TABLE bootstrap_v3_commitments (
 operation_id UUID PRIMARY KEY REFERENCES bootstrap_v3_operations(id) ON DELETE RESTRICT,
 record JSONB NOT NULL,receipt JSONB NOT NULL
);
CREATE TABLE bootstrap_v3_catalog_manifest (
 id BOOLEAN PRIMARY KEY CHECK(id),record JSONB NOT NULL
);

CREATE FUNCTION bootstrap_v3_id(op UUID,slot TEXT) RETURNS UUID LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE h TEXT:=bootstrap_proof_digest(jsonb_build_array('roost-bootstrap-v3-child-id',op,slot));BEGIN
 RETURN (substr(h,1,8)||'-'||substr(h,9,4)||'-4'||substr(h,14,3)||'-8'||substr(h,18,3)||'-'||substr(h,21,12))::uuid;
END $$;
CREATE FUNCTION bootstrap_v3_native_digest(v JSONB) RETURNS TEXT LANGUAGE plpgsql IMMUTABLE AS $$
BEGIN RETURN encode(sha256(convert_to(v::text,'UTF8')),'hex');END $$;
CREATE FUNCTION bootstrap_v3_assert(ok BOOLEAN,reason TEXT) RETURNS VOID LANGUAGE plpgsql AS $$
BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'bootstrap_v3_denied: %',reason;END IF;END $$;
CREATE FUNCTION bootstrap_v3_mode(write_mode BOOLEAN) RETURNS BIGINT LANGUAGE plpgsql VOLATILE AS $$
DECLARE f BIGINT;BEGIN
 PERFORM bootstrap_v3_assert(current_setting('session_replication_role')='origin'
  AND current_schemas(true)=ARRAY['pg_catalog','public']::name[]
  AND current_setting('transaction_isolation')=CASE WHEN write_mode THEN 'serializable' ELSE 'repeatable read' END
  AND current_setting('transaction_read_only')=CASE WHEN write_mode THEN 'off' ELSE 'on' END,'transaction_mode');
 IF write_mode THEN SELECT revision INTO f FROM ready_source_fence WHERE id=1 FOR UPDATE;
 ELSE SELECT revision INTO f FROM ready_source_fence WHERE id=1;END IF;
 PERFORM bootstrap_v3_assert(f>0,'source_lock');RETURN f;
END $$;

-- Every primary write and automatic descendant is specified here. This is
-- deliberately the same CLOSED order as v3ProjectionRecipe, including fan-out.
CREATE FUNCTION bootstrap_v3_recipe(p JSONB,heads JSONB) RETURNS JSONB LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE a JSONB:=p->'authority'->'attachment';c JSONB:=p->'envelope'->'signed'->'payload'->'context';
 hostkey TEXT:=a->>'workspaceId'||':'||(a->'generation'->>'hostId');base JSONB;result JSONB:='[]';w JSONB;h JSONB;BEGIN
 base:=jsonb_build_array(
 jsonb_build_array('reservation','reservation','v3_reservation',p->'command'->>'operationId',jsonb_build_object('attachmentId',p->'command'->'attachmentId','attachmentDigest',p->'command'->'expected'->'attachmentDigest','planDigest',bootstrap_proof_digest(p)),jsonb_build_array('projection'),NULL,false,false),
 jsonb_build_array('ticket','ticket','ticket',a->>'ticketId',p->'envelope',jsonb_build_array('lifecycle','attestation'),NULL,true,false),
 jsonb_build_array('ticket','ticket-audit','bootstrap_audit',a->>'ticketId'||':issue',jsonb_build_object('ticketId',a->'ticketId','envelopeDigest',p->'link'->'ticketEnvelopeDigest'),jsonb_build_array('lifecycle','attestation'),'ticket',false,false),
 jsonb_build_array('ticket','ticket-issue','ticket_lifecycle',c->>'issueEventId',jsonb_build_object('ticketId',a->'ticketId','action','issue','state','issued'),jsonb_build_array('lifecycle','attestation'),'ticket',false,false),
 jsonb_build_array('channel','channel-generation','channel_generation',c->'channel'->'snapshot'->>'generation',c->'channel'->'snapshot',jsonb_build_array('transport','attestation'),NULL,true,false),
 jsonb_build_array('channel','channel-grant','channel_grant',c->>'channelGrantId',jsonb_build_object('ticketId',a->'ticketId','ticketDigest',p->'link'->'ticketEnvelopeDigest','channel',c->'channel'),jsonb_build_array('transport','attestation'),NULL,true,false),
 jsonb_build_array('channel','channel-history','channel_history',c->>'channelHistoryId',jsonb_build_object('grantId',c->'channelGrantId','snapshot',c->'channel'->'snapshot'),jsonb_build_array('transport','attestation'),NULL,true,false),
 jsonb_build_array('channel','channel-head','channel_head',hostkey,jsonb_build_object('historyId',c->'channelHistoryId','snapshot',c->'channel'->'snapshot'),jsonb_build_array('transport','attestation'),'channel-history',true,true),
 jsonb_build_array('channel','channel-audit','channel_audit',c->>'channelHistoryId',jsonb_build_object('historyId',c->'channelHistoryId','grantId',c->'channelGrantId'),jsonb_build_array('transport'),'channel-history',false,false),
 jsonb_build_array('attempt','attempt','attempt',c->>'attemptId',jsonb_build_object('ticketId',a->'ticketId','ticketDigest',p->'link'->'ticketEnvelopeDigest','requestId',a->'requestId','binding',p->'authority'->'intent'->'binding','target',p->'authority'->'intent'->'target'),jsonb_build_array('lifecycle','attestation'),NULL,false,false),
 jsonb_build_array('attempt','attempt-history','bootstrap_history',c->>'attemptHistoryId',jsonb_build_object('attemptId',c->'attemptId','state','consumed'),jsonb_build_array('lifecycle','attestation'),'attempt',false,false),
 jsonb_build_array('attempt','attempt-head','bootstrap_head',hostkey,jsonb_build_object('attemptId',c->'attemptId','historyId',c->'attemptHistoryId'),jsonb_build_array('lifecycle','attestation'),'attempt-history',false,true),
 jsonb_build_array('attempt','attempt-audit','bootstrap_audit',c->>'attemptHistoryId'||':consume',jsonb_build_object('attemptId',c->'attemptId','historyId',c->'attemptHistoryId'),jsonb_build_array('lifecycle','attestation'),'attempt-history',false,false),
 jsonb_build_array('attempt','ticket-consume','ticket_lifecycle',c->>'consumeEventId',jsonb_build_object('ticketId',a->'ticketId','attemptId',c->'attemptId','historyId',c->'attemptHistoryId','action','consume','state','consumed'),jsonb_build_array('lifecycle','attestation'),'attempt',false,false),
 jsonb_build_array('link','proof-link','proof_link',c->>'linkId',p->'link',jsonb_build_array('proof'),NULL,false,false),
 jsonb_build_array('seal','attempt-seal','v3_seal',c->>'attemptId',p->'seal',jsonb_build_array('projection'),NULL,false,false),
 jsonb_build_array('seal','seal-audit','v3_seal_audit',c->>'receiptEventId',jsonb_build_object('operationId',p->'command'->'operationId','planDigest',bootstrap_proof_digest(p),'sealDigest',p->'link'->'sealDigest'),jsonb_build_array('projection'),'attempt-seal',false,false));
 FOR w IN SELECT value FROM jsonb_array_elements(base) LOOP
  result:=result||jsonb_build_array(jsonb_build_object('phase',w->0,'slot',w->1,'source',w->2,'key',w->3,'binding',w->4,'families',w->5,'parentSlot',w->6,'update',w->8,'authorityFor',NULL));
  IF (w->>7)::boolean THEN
   FOR h IN SELECT value FROM jsonb_array_elements(heads) WHERE value->>'fanout'='true' ORDER BY convert_to(value->>'decisionId','UTF8') LOOP
    result:=result||jsonb_build_array(jsonb_build_object('phase',w->0,'slot',w->>1||':authority:'||(h->>'decisionId'),
     'source','decision_authority_event','key','derived','binding',NULL,'families',jsonb_build_array('attestation'),'parentSlot',w->1,'update',false,'authorityFor',h->'decisionId'));
   END LOOP;
  END IF;
 END LOOP;RETURN result;
END $$;

