CREATE FUNCTION bootstrap_v3_wire(v JSONB,node_id INT,depth INT) RETURNS BOOLEAN LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE s JSONB:=bootstrap_v3_wire_schema()->'nodes'->node_id;k TEXT;child JSONB;c JSONB;t TEXT:=jsonb_typeof(v);n NUMERIC;BEGIN
 IF depth>32 OR v IS NULL OR s IS NULL THEN RETURN false;END IF;
 CASE s->>'kind'
 WHEN 'literal' THEN RETURN v=s->'value';
 WHEN 'enum' THEN RETURN EXISTS(SELECT 1 FROM jsonb_array_elements(s->'values') x WHERE x=v);
 WHEN 'nullable' THEN RETURN v='null'::jsonb OR bootstrap_v3_wire(v,(s->>'inner')::int,depth+1);
 WHEN 'union' THEN
  FOR child IN SELECT value FROM jsonb_array_elements(s->'options') LOOP
   IF bootstrap_v3_wire(v,(child#>>'{}')::int,depth+1) THEN RETURN true;END IF;
  END LOOP;RETURN false;
 WHEN 'object' THEN
  IF t<>'object' OR (SELECT count(*) FROM jsonb_object_keys(v))<>(SELECT count(*) FROM jsonb_object_keys(s->'fields')) THEN RETURN false;END IF;
  FOR k,child IN SELECT key,value FROM jsonb_each(s->'fields') LOOP
   IF NOT bootstrap_v3_wire(v->k,(child#>>'{}')::int,depth+1) THEN RETURN false;END IF;
  END LOOP;
 WHEN 'array' THEN
  IF t<>'array' THEN RETURN false;END IF;
  IF jsonb_array_length(v)<(s->>'min')::int OR jsonb_array_length(v)>(s->>'max')::int THEN RETURN false;END IF;
  FOR child IN SELECT value FROM jsonb_array_elements(v) LOOP
   IF NOT bootstrap_v3_wire(child,(s->>'inner')::int,depth+1) THEN RETURN false;END IF;
  END LOOP;
 WHEN 'string','number' THEN
  IF t<>s->>'kind' THEN RETURN false;END IF;
  FOR c IN SELECT value FROM jsonb_array_elements(s->'checks') LOOP
   n:=CASE WHEN t='number' THEN (v#>>'{}')::numeric ELSE length(v#>>'{}') END;
   IF c->>'kind'='uuid' AND (v#>>'{}') !~ '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$'
    OR c->>'kind'='regex' AND (v#>>'{}') !~ (c->>'regex')
    OR c->>'kind'='datetime' AND NOT bootstrap_proof_time(v)
    OR c->>'kind'='int' AND n<>trunc(n)
    OR c->>'kind'='min' AND (n<(c->>'value')::numeric OR c->>'inclusive'='false' AND n=(c->>'value')::numeric)
    OR c->>'kind'='max' AND (n>(c->>'value')::numeric OR c->>'inclusive'='false' AND n=(c->>'value')::numeric)
    OR c->>'kind'='length' AND n<>(c->>'value')::numeric THEN RETURN false;END IF;
  END LOOP;
 ELSE RETURN false;
 END CASE;RETURN true;
 EXCEPTION WHEN OTHERS THEN RETURN false;
END $$;

CREATE FUNCTION bootstrap_v3_authorize(p JSONB) RETURNS VOID LANGUAGE plpgsql VOLATILE AS $$
DECLARE s JSONB:=p->'authority';a JSONB:=s->'attachment';i JSONB:=s->'intent';b JSONB:=i->'binding';o JSONB:=s->'owner';
 e JSONB:=p->'envelope';c JSONB:=e->'signed'->'payload'->'context';l JSONB:=s->'lifecycle';ch JSONB:=s->'channel';snap JSONB:=ch->'snapshot';
 issuer JSONB:=s->'issuer';actual JSONB;expected JSONB;link JSONB;seal JSONB;field TEXT;w UUID:=(a->>'workspaceId')::uuid;
 attached bootstrap_proof_attachments;accepted decision_acceptances;auth decision_owner_auth_evidence;ih bootstrap_issuer_history;ik bootstrap_issuer_history;
 anchor trusted_provider_ticket_keys;host worker_identity_lifecycle;installation worker_identity_lifecycle;oldticket worker_bootstrap_tickets;prior worker_bootstrap_lifecycle_events;
 head worker_transport_heads;oldchannel worker_transport_history;credential api_keys;f BIGINT;atime TIMESTAMPTZ;BEGIN
 PERFORM bootstrap_v3_assert(bootstrap_v3_wire(p,(bootstrap_v3_wire_schema()->>'root')::int,0),'wire_shape');
 PERFORM bootstrap_proof_bytes(p,0);f:=bootstrap_v3_mode(true);atime:=(s->>'at')::timestamptz;
 PERFORM bootstrap_v3_assert(p->'command'->>'attachmentId'=s->>'attachmentId'
  AND p->'command'->'expected'=jsonb_build_object('attachmentDigest',s->'attachmentDigest','authorityRevision',s->'authorityRevision','authorityDigest',s->'authorityDigest','sourceDigest',s->'sourceDigest','fence',s->'fence')
  AND s->>'fence'=f::text AND s->>'writerXid'=pg_current_xact_id()::text AND atime<=clock_timestamp()
  AND atime>=clock_timestamp()-interval '5 minutes' AND (i->>'expiresAt')::timestamptz>clock_timestamp()
  AND (i->>'expiresAt')::timestamptz<=atime+interval '120 seconds','fresh_command');
 SELECT * INTO attached FROM bootstrap_proof_attachments WHERE id=(s->>'attachmentId')::uuid;
 PERFORM bootstrap_v3_assert(attached.workspace_id=w AND attached.record=a AND attached.record_bytes=bootstrap_proof_bytes(a,0)
  AND attached.record_digest=s->>'attachmentDigest' AND attached.record_digest=bootstrap_proof_digest(a)
  AND a=i->'proofAuthority' AND NOT EXISTS(SELECT 1 FROM worker_bootstrap_tickets WHERE id=attached.ticket_id),'attachment');
 PERFORM bootstrap_v3_assert(bootstrap_proof_owner(w,attached.decision_id,attached.decision_revision,'workerBootstrapProofAuthority',a)=(attached.record->>'ownerId')::uuid,'attachment_owner');
 -- Both public objects must have been accepted together. A caller cannot add
 -- a target/channel to a decision that only reserved proof keys.
 PERFORM bootstrap_v3_assert(bootstrap_proof_owner(w,attached.decision_id,attached.decision_revision,'workerBootstrapAdmissionV3',i)=(a->>'ownerId')::uuid,'issuance_owner');
 SELECT * INTO accepted FROM decision_acceptances WHERE decision_id=attached.decision_id;
 SELECT * INTO auth FROM decision_owner_auth_evidence WHERE decision_id=attached.decision_id AND acceptance_id=accepted.id;
 PERFORM bootstrap_v3_assert(decision_attestation_owner(attached.decision_id,accepted.id)
  AND o=jsonb_build_object('id',a->'ownerId','decisionId',a->'decisionId','decisionRevision',a->'decisionRevision',
   'acceptedAt',to_char(accepted.created_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
   'authenticatedAt',auth.record->'authTime','expiresAt',i->'expiresAt','intentDigest',bootstrap_proof_digest(i))
  AND (auth.record->>'authTime')::timestamptz>=clock_timestamp()-interval '5 minutes'
  AND (auth.record->>'authTime')::timestamptz<=accepted.created_at AND accepted.created_at<=atime,'owner_authentication');
 PERFORM bootstrap_v3_assert(bootstrap_proof_lifecycle(w,attached.installation_id,attached.host_id,attached.installation_generation,attached.host_generation,attached.installation_lifecycle_id,attached.host_lifecycle_id),'lifecycle');
 SELECT * INTO host FROM worker_identity_lifecycle WHERE id=attached.host_lifecycle_id;
 SELECT * INTO installation FROM worker_identity_lifecycle WHERE id=attached.installation_lifecycle_id;
 SELECT * INTO anchor FROM trusted_provider_ticket_keys WHERE workspace_id=w AND installation_id=attached.installation_id;
 PERFORM bootstrap_v3_assert(l=jsonb_build_object('installationLifecycleId',installation.id,'hostLifecycleId',host.id,'installationGeneration',installation.generation,
  'hostGeneration',host.generation,'hostId',host.subject_id,'hostEnabled',true,'installationEnabled',true)
  AND b=jsonb_build_object('workspaceId',w,'installationId',installation.subject_id,'installationEpoch',installation.epoch,'hostId',host.subject_id,'hostEpoch',host.epoch,
   'hostFingerprint',host.record->'intent'->'hostFingerprint','ticketKeyId',anchor.key_id,'ticketKeyEpoch',anchor.epoch,'ticketPublicKeyDigest',anchor.public_key_digest),'identity_binding');
 SELECT * INTO ih FROM bootstrap_issuer_history WHERE workspace_id=w ORDER BY revision DESC LIMIT 1;
 SELECT * INTO ik FROM bootstrap_issuer_history WHERE workspace_id=w AND record->'intent'->>'targetEpoch'=anchor.epoch::text
  AND record->'intent'->>'action' IN ('create','adopt','stage') ORDER BY revision DESC LIMIT 1;
 PERFORM bootstrap_v3_assert(ih.revision::text=issuer->>'revision' AND ih.record_digest=issuer->>'historyDigest'
  AND bootstrap_proof_public_material(issuer->'material') AND issuer->'material'=ik.record->'intent'->'material'
  AND issuer->>'authorizationDigest'=bootstrap_proof_digest(jsonb_build_object('domain','roost-bootstrap-v3-issuer-authorization-v1',
   'issuerRecordDigest',ik.record_digest,'decisionId',attached.decision_id,'acceptanceId',accepted.id,'intentDigest',bootstrap_proof_digest(i)))
  AND issuer->>'workspaceId'=w::text AND issuer->>'installationId'=attached.installation_id::text AND issuer->>'epoch'=anchor.epoch::text
  AND issuer->'material'->>'keyId'=anchor.key_id AND issuer->'material'->>'publicKeyDigest'=anchor.public_key_digest
  AND issuer->>'validFrom'=to_char(greatest(accepted.created_at,(CASE WHEN ik.record->'intent'->>'action'='stage' THEN ik.record->'intent'->>'activatesAt' ELSE ik.record->>'at' END)::timestamptz) AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')
  AND issuer->'expiresAt'=i->'expiresAt' AND (issuer->>'validFrom')::timestamptz<=atime
  AND (issuer->>'expiresAt')::timestamptz>=(i->>'expiresAt')::timestamptz
  AND NOT EXISTS(SELECT 1 FROM bootstrap_issuer_history x WHERE x.workspace_id=w AND x.record->'intent'->>'targetEpoch'=anchor.epoch::text AND x.record->'intent'->>'action' IN ('revoke','retire'))
  AND (ik.record->'intent'->>'action'<>'stage' OR EXISTS(SELECT 1 FROM bootstrap_issuer_history x WHERE x.workspace_id=w AND x.record->'intent'->>'targetEpoch'=anchor.epoch::text AND x.record->'intent'->>'action'='cutover')),'issuer');
 FOREACH field IN ARRAY ARRAY['local_worker','roost_server'] LOOP
  SELECT jsonb_agg(record ORDER BY revision) INTO actual FROM bootstrap_proof_key_history WHERE workspace_id=w AND principal=field;
  PERFORM bootstrap_v3_assert(actual=s->CASE WHEN field='local_worker' THEN 'workerHistory' ELSE 'serverHistory' END
   AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(actual) x WHERE (x->>'at')::timestamptz>accepted.created_at),'proof_history');
 END LOOP;
 PERFORM bootstrap_proof_reference(w,a->'worker',clock_timestamp(),a->'generation');
 PERFORM bootstrap_proof_reference(w,a->'server',clock_timestamp(),'null');
 SELECT jsonb_agg(to_jsonb(digest) ORDER BY digest COLLATE "C") INTO actual FROM (
  SELECT public_key_digest digest FROM trusted_provider_ticket_keys WHERE workspace_id=w
  UNION SELECT record->'intent'->'material'->>'publicKeyDigest' FROM bootstrap_issuer_history WHERE workspace_id=w AND record->'intent'->'material'<>'null'
  UNION SELECT encode(sha256(decode('302a300506032b6570032100'||(record->'material'->>'publicKey'),'hex')),'hex') FROM decision_attestation_key_history WHERE workspace_id=w AND record->'material'<>'null'
 ) x WHERE digest IS NOT NULL;
 PERFORM bootstrap_v3_assert(actual=s->'reservedPublicKeyDigests'
  AND NOT EXISTS(SELECT 1 FROM bootstrap_proof_key_history h WHERE h.workspace_id=w AND (h.record->'intent'->'material'->>'publicKeyDigest' IN (SELECT jsonb_array_elements_text(actual))
   OR h.record->'intent'->'material'->>'keyId'=issuer->'material'->>'keyId'))
  AND NOT EXISTS(SELECT 1 FROM bootstrap_proof_key_history h JOIN bootstrap_proof_key_history j ON j.workspace_id=h.workspace_id AND j.principal<>h.principal
   WHERE h.workspace_id=w AND (h.record->'intent'->'material'->>'keyId'=j.record->'intent'->'material'->>'keyId' OR h.record->'intent'->'material'->>'publicKeyDigest'=j.record->'intent'->'material'->>'publicKeyDigest')),'key_separation');
 SELECT * INTO oldticket FROM worker_bootstrap_tickets WHERE workspace_id=w AND host_id=attached.host_id ORDER BY generation DESC LIMIT 1;
 SELECT * INTO credential FROM api_keys WHERE workspace_id=w AND worker_host_id=attached.host_id ORDER BY worker_binding_epoch DESC LIMIT 1;
 PERFORM bootstrap_v3_assert(a->>'requestId'=i->>'requestId' AND a->>'purpose'=i->>'purpose'
  AND (a->>'enrollmentGeneration')::int=coalesce(oldticket.generation,0)+1
  AND i->'baseline'->>'enrollmentGeneration'=coalesce(oldticket.generation,0)::text
  AND (i->'target'->>'epoch')::int=coalesce(credential.worker_binding_epoch,0)+1
  AND i->'baseline'->>'credentialHighWater'=coalesce(credential.worker_binding_epoch,0)::text
  AND i->'target'->>'version'='1' AND NOT EXISTS(SELECT 1 FROM api_keys WHERE id=(i->'target'->>'id')::uuid OR encode(sha256(convert_to('roost-worker-ticket-v1:'||key_hash,'UTF8')),'hex')=i->'target'->>'fingerprint'),'credential_high_water');
 IF a->>'purpose'='first_enrollment' THEN
  PERFORM bootstrap_v3_assert(oldticket.id IS NULL AND credential.id IS NULL AND a->'prior'='null' AND i->'prior'='null' AND s->'prior'='null' AND i->'baseline'->'credential'='null','first_enrollment');
 ELSE
  SELECT * INTO prior FROM worker_bootstrap_lifecycle_events WHERE ticket_id=oldticket.id ORDER BY revision DESC LIMIT 1;
  PERFORM bootstrap_v3_assert(NOT credential.active AND credential.revoked_at IS NOT NULL AND prior.record->>'state' IN ('revoked','expired','delivery_unknown')
   AND a->'prior'->>'ticketId'=oldticket.id::text AND a->'prior'->>'decisionId'=oldticket.decision_id::text
   AND a->'prior'->>'requestId'=oldticket.request_id::text AND a->'prior'->>'enrollmentGeneration'=oldticket.generation::text
   AND a->>'ticketId'<>oldticket.id::text AND a->>'decisionId'<>oldticket.decision_id::text AND a->>'requestId'<>oldticket.request_id::text
   AND credential.id=oldticket.target_id AND i->'prior'=jsonb_build_object('ticketId',oldticket.id,'ticketDigest',oldticket.ticket_digest,'attemptId',prior.attempt_id,
    'generation',oldticket.generation,'credentialEpoch',oldticket.credential_epoch,'historyDigest',prior.record_digest,'state',prior.record->'state','workspaceId',w,'hostId',attached.host_id)
   AND s->'prior'=jsonb_build_object('ticketId',oldticket.id,'decisionId',oldticket.decision_id,'requestId',oldticket.request_id,'enrollmentGeneration',oldticket.generation,
    'credentialId',credential.id,'credentialEpoch',credential.worker_binding_epoch,'credentialRevoked',true,'terminal',true,'predecessor',i->'prior')
   AND i->'baseline'->'credential'=jsonb_build_object('id',credential.id,'epoch',credential.worker_binding_epoch,'version',credential.credential_version,'fingerprint',encode(sha256(convert_to('roost-worker-ticket-v1:'||credential.key_hash,'UTF8')),'hex')),'recovery');
 END IF;
 SELECT * INTO head FROM worker_transport_heads WHERE workspace_id=w AND host_id=attached.host_id;
 SELECT * INTO oldchannel FROM worker_transport_history WHERE id=head.history_id;
 PERFORM bootstrap_v3_assert(transport_bootstrap_shape(snap) AND snap->>'recordDigest'=bootstrap_lifecycle_digest(snap-'recordDigest')
  AND ch->>'acceptanceId'=accepted.id::text AND ch->>'previousRevision'=coalesce(head.revision,0)::text
  AND ch->'previousDigest'=coalesce(to_jsonb(head.record_digest),'null') AND ch->>'previousHighWater'=coalesce(head.high_water_epoch,0)::text
  AND (head.history_id IS NULL OR head.state='revoked') AND NOT EXISTS(SELECT 1 FROM worker_transport_history WHERE workspace_id=w AND host_id=attached.host_id
   AND (generation_id=(snap->>'generation')::uuid OR current_pin=snap->>'leafPin' OR staged_pin=snap->>'leafPin'))
  AND snap->'binding'=b AND snap->'purpose'=a->'purpose' AND snap->'hostGeneration'=l->'hostGeneration' AND snap->'installationGeneration'=l->'installationGeneration'
  AND (snap->>'revision')::int=coalesce(head.revision,0)+1 AND (snap->>'certificateEpoch')::int=coalesce(head.high_water_epoch,0)+1
  AND snap->'issuerRevision'=issuer->'revision' AND snap->'issuerHistoryDigest'=issuer->'historyDigest'
  AND (snap->>'validFrom')::timestamptz<=atime AND (snap->>'certificateNotBefore')::timestamptz<=atime
  AND (snap->>'expiresAt')::timestamptz>=(i->>'expiresAt')::timestamptz AND (snap->>'certificateNotAfter')::timestamptz>=(i->>'expiresAt')::timestamptz
  AND (snap->'cutoverAt'='null' OR (snap->>'cutoverAt')::timestamptz>clock_timestamp()),'channel');
 PERFORM bootstrap_v3_assert(i->'channel'->'revision'=snap->'revision' AND i->'channel'->'certificateEpoch'=snap->'certificateEpoch'
  AND i->'channel'->'highWaterEpoch'=snap->'highWaterEpoch' AND i->'channel'->'validUntil'=snap->'expiresAt'
  AND i->'channel'->'profile'->'origin'=snap->'origin' AND i->'channel'->'profile'->'serverName'=snap->'serverName'
  AND i->'channel'->'profile'->'trust'->'caDigest'=snap->'caDigest' AND i->'channel'->'profile'->'certificate'->'fingerprint'=snap->'leafPin'
  AND i->'channel'->'profile'->'certificate'->'hostname'=snap->'serverName'
  AND i->'channel'->'profile'->'bootstrap'->'fingerprint'=snap->'leafPin'
  AND i->'channel'->'profile'->'certificate'->'notBefore'=snap->'certificateNotBefore' AND i->'channel'->'profile'->'certificate'->'notAfter'=snap->'certificateNotAfter'
  AND i->'channel'->'profile'->'bootstrap'->'evidenceDigest'=snap->'certificateEvidenceDigest' AND i->'channel'->'profile'->'resolver'->'policy'=snap->'resolverPolicy','channel_binding');
 -- Zod's production DNS-origin refinement is an effect, not structural schema.
 PERFORM bootstrap_v3_assert((split_part(snap->>'origin',':',3))::int<=65535
  AND snap->>'serverName'~'^[a-z0-9]([a-z0-9.-]*[a-z0-9])?$' AND position('.' IN snap->>'serverName')>0
  AND snap->>'serverName'!~'^[0-9.]+$' AND snap->>'serverName'!~'(^|\.)(localhost|local|internal|invalid|test|example|onion)$'
  AND NOT EXISTS(SELECT 1 FROM unnest(string_to_array(snap->>'serverName','.')) label WHERE length(label) NOT BETWEEN 1 AND 63 OR label~'^-|-$'),'production_origin');
 expected:=jsonb_build_object('operationId',p->'command'->'operationId','attachmentId',s->'attachmentId','attachmentDigest',s->'attachmentDigest',
  'authorityRevision',s->'authorityRevision','authorityDigest',s->'authorityDigest','sourceDigest',s->'sourceDigest','sourceFence',s->'fence','issuer',issuer,'lifecycle',l,'channel',ch);
 FOREACH field IN ARRAY ARRAY['attemptId','linkId','channelGrantId','channelHistoryId','issueEventId','consumeEventId','attemptHistoryId','receiptEventId'] LOOP
  expected:=expected||jsonb_build_object(field,bootstrap_v3_id((p->'command'->>'operationId')::uuid,field));
 END LOOP;
 PERFORM bootstrap_v3_assert(c=expected AND e->'signed'->'payload'=jsonb_build_object('version','worker-bootstrap-owner-ticket-v3','id',a->'ticketId','ownerId',a->'ownerId',
  'ownerAuthAt',o->'authenticatedAt','issuedAt',s->'at','decisionId',a->'decisionId','decisionRevision',a->'decisionRevision','decisionIntentDigest',o->'intentDigest',
  'intent',i,'context',c,'contentDomain','roost-worker-bootstrap-owner-ticket-content-v3')
  AND e->'decision'->'payload'=jsonb_build_object('id',a->'decisionId','revision',a->'decisionRevision','ownerId',a->'ownerId','authority','owner_reserved','state','accepted',
   'intentDigest',o->'intentDigest','acceptedAt',o->'acceptedAt','expiresAt',o->'expiresAt'),'ticket_transcripts');
 link:=jsonb_build_object('version','bootstrap-proof-ticket-link-v3','domain','roost-bootstrap-proof-ticket-link-v3','operationId',c->'operationId','attachmentId',s->'attachmentId','attachmentDigest',s->'attachmentDigest',
  'ticketId',a->'ticketId','ticketContentDigest',bootstrap_proof_digest(jsonb_build_array('roost-bootstrap-signing-binary-v1','roost-worker-bootstrap-owner-ticket-content-v3',a,c,e->'signed'->'payload')),
  'ticketEnvelopeDigest',bootstrap_proof_digest(jsonb_build_array('roost-worker-bootstrap-owner-ticket-envelope-v3',e)),'attemptId',c->'attemptId','context',c);
 seal:=jsonb_build_object('version','bootstrap-proof-attempt-seal-v3','domain','roost-bootstrap-binding-attempt-seal-v3','linkBinding',link,
  'linkBindingDigest',bootstrap_proof_digest(jsonb_build_array('roost-bootstrap-proof-ticket-link-v3',link)),'attachment',a,'sealedAt',s->'at','state','sealed');
 PERFORM bootstrap_v3_assert(p->'seal'->'payload'=seal AND p->'link'=(link||jsonb_build_object('sealDigest',bootstrap_proof_digest(jsonb_build_array('roost-bootstrap-binding-attempt-seal-v3',p->'seal')))),'seal_transcript');
END $$;

CREATE FUNCTION bootstrap_v3_binding(role TEXT,rkey TEXT,r JSONB,p JSONB) RETURNS TEXT LANGUAGE plpgsql VOLATILE AS $$
DECLARE s JSONB:=p->'authority';a JSONB:=s->'attachment';b JSONB:=s->'intent'->'binding';x JSONB;matches JSONB;BEGIN
 -- Existing own rows retain their binding only when their COMPLETE current
 -- native row still matches that immutable witness. No latest-row shortcut.
 SELECT jsonb_agg(DISTINCT record->'after'->'bindingDigest') INTO matches FROM bootstrap_v3_mutations
 WHERE record->'after'->>'source'=role AND record->'after'->>'key'=rkey AND after_digest=bootstrap_v3_native_digest(r);
 IF matches IS NOT NULL THEN
  PERFORM bootstrap_v3_assert(jsonb_array_length(matches)=1,'ambiguous_binding');RETURN matches->>0;
 END IF;
 IF role='decision' THEN x:=jsonb_build_object('decisionId',r->'id','fanout',coalesce(r->>'authority_revision'='1',false));
 ELSIF role='workspace' AND rkey=a->>'workspaceId' THEN x:=jsonb_build_object('workspaceId',a->'workspaceId','ownerId',a->'ownerId');
 ELSIF role='membership' AND rkey=(a->>'workspaceId'||':'||(a->>'ownerId')) THEN x:=jsonb_build_object('workspaceId',a->'workspaceId','ownerId',a->'ownerId','role','owner');
 ELSIF role='decision_revision' AND rkey=(a->>'decisionId'||':'||(a->>'decisionRevision')) THEN x:=jsonb_build_object('decisionId',a->'decisionId','revision',a->'decisionRevision','intentDigest',s->'owner'->'intentDigest','attachmentDigest',s->'attachmentDigest');
 ELSIF role='decision_acceptance' AND rkey=a->>'decisionId' THEN x:=s->'owner';
 ELSIF role='owner_auth' AND rkey=(a->>'decisionId'||':'||(s->'owner'->>'authenticatedAt')) THEN x:=jsonb_build_object('decisionId',a->'decisionId','ownerId',a->'ownerId','authenticatedAt',s->'owner'->'authenticatedAt');
 ELSIF role='identity' AND rkey=s->'lifecycle'->>'installationLifecycleId' THEN x:=jsonb_build_object('subjectId',a->'installationId','generation',a->'generation'->'installationGeneration','enabled',true);
 ELSIF role='identity' AND rkey=s->'lifecycle'->>'hostLifecycleId' THEN x:=jsonb_build_object('subjectId',a->'generation'->'hostId','generation',a->'generation'->'hostGeneration','enabled',true);
 ELSIF role='host' AND rkey=b->>'hostId' THEN x:=jsonb_build_object('hostId',b->'hostId','epoch',b->'hostEpoch','fingerprint',b->'hostFingerprint','enabled',true);
 ELSIF role='anchor' AND rkey=a->>'installationId' THEN x:=jsonb_build_object('workspaceId',a->'workspaceId','installationId',a->'installationId','epoch',b->'installationEpoch','keyId',b->'ticketKeyId','keyEpoch',b->'ticketKeyEpoch','publicKeyDigest',b->'ticketPublicKeyDigest');
 ELSIF role='issuer' AND rkey=(a->>'installationId'||':'||(s->'issuer'->>'revision')) THEN x:=s->'issuer';
 ELSIF role='proof_attachment' AND rkey=s->>'attachmentId' THEN x:=a;
 ELSIF role='proof_key' THEN x:=r->'record';
 ELSE x:=jsonb_build_object('source',role,'key',rkey,'nativeDigest',bootstrap_v3_native_digest(r));END IF;
 RETURN bootstrap_proof_digest(x);
END $$;

CREATE FUNCTION bootstrap_v3_inventory(p JSONB) RETURNS JSONB LANGUAGE plpgsql VOLATILE AS $$
DECLARE w UUID:=(p->'authority'->'attachment'->>'workspaceId')::uuid;rows JSONB;heads JSONB;f BIGINT;BEGIN
 -- Hash secret-bearing native rows inside SQL; return only public logical
 -- bindings and full-row digests. No source role is omitted when empty.
 WITH source(role,rkey,r) AS (
 SELECT 'workspace',x.id::text,to_jsonb(x) FROM workspaces x WHERE x.id=w
 UNION ALL SELECT 'membership',x.workspace_id::text||':'||x.user_id::text,to_jsonb(x) FROM workspace_memberships x WHERE x.workspace_id=w
 UNION ALL SELECT 'decision',x.id::text,to_jsonb(x) FROM decisions x WHERE x.workspace_id=w
 UNION ALL SELECT 'decision_revision',x.decision_id::text||':'||x.version::text,to_jsonb(x) FROM decision_revisions x WHERE x.workspace_id=w
 UNION ALL SELECT 'decision_acceptance',x.decision_id::text,to_jsonb(x) FROM decision_acceptances x WHERE x.workspace_id=w
 UNION ALL SELECT 'owner_auth',x.decision_id::text||':'||(x.record->>'authTime'),to_jsonb(x) FROM decision_owner_auth_evidence x WHERE x.workspace_id=w
 UNION ALL SELECT 'identity',x.id::text,to_jsonb(x) FROM worker_identity_lifecycle x WHERE x.workspace_id=w
 UNION ALL SELECT 'host',x.id::text,to_jsonb(x) FROM agent_hosts x WHERE x.workspace_id=w
 UNION ALL SELECT 'issuer',k.installation_id::text||':'||x.revision::text,to_jsonb(x) FROM bootstrap_issuer_history x JOIN trusted_provider_ticket_keys k ON k.workspace_id=x.workspace_id WHERE x.workspace_id=w
 UNION ALL SELECT 'attestation_key',x.id::text,to_jsonb(x) FROM decision_attestation_key_history x WHERE x.workspace_id=w
 UNION ALL SELECT 'anchor',x.installation_id::text,to_jsonb(x) FROM trusted_provider_ticket_keys x WHERE x.workspace_id=w
 UNION ALL SELECT 'ticket',x.id::text,to_jsonb(x) FROM worker_bootstrap_tickets x WHERE x.workspace_id=w
 UNION ALL SELECT 'attempt',x.id::text,to_jsonb(x) FROM worker_bootstrap_attempts x WHERE x.workspace_id=w
 UNION ALL SELECT 'credential',x.id::text,to_jsonb(x) FROM api_keys x WHERE x.workspace_id=w
 UNION ALL SELECT 'handoff',x.id::text,to_jsonb(x) FROM worker_credential_handoffs x WHERE x.workspace_id=w
 UNION ALL SELECT 'ticket_lifecycle',x.id::text,to_jsonb(x) FROM worker_bootstrap_lifecycle_events x JOIN worker_bootstrap_tickets t ON t.id=x.ticket_id WHERE t.workspace_id=w
 UNION ALL SELECT 'bootstrap_history',x.id::text,to_jsonb(x) FROM worker_bootstrap_history x JOIN worker_bootstrap_attempts a ON a.id=x.attempt_id WHERE a.workspace_id=w
 UNION ALL SELECT 'dispatch',x.id::text,to_jsonb(x) FROM worker_bootstrap_dispatch_history x JOIN worker_bootstrap_attempts a ON a.id=x.attempt_id WHERE a.workspace_id=w
 UNION ALL SELECT 'completion',x.id::text,to_jsonb(x) FROM worker_bootstrap_completions x WHERE x.workspace_id=w
 UNION ALL SELECT 'proof_key',x.principal||':'||x.revision::text,to_jsonb(x) FROM bootstrap_proof_key_history x WHERE x.workspace_id=w
 UNION ALL SELECT 'proof_attachment',x.id::text,to_jsonb(x) FROM bootstrap_proof_attachments x WHERE x.workspace_id=w
 UNION ALL SELECT 'proof_link',x.id::text,to_jsonb(x) FROM bootstrap_proof_ticket_links x WHERE x.workspace_id=w
 UNION ALL SELECT 'channel_generation',x.id::text,to_jsonb(x) FROM worker_transport_generations x WHERE x.workspace_id=w
 UNION ALL SELECT 'channel_grant',x.id::text,to_jsonb(x) FROM worker_transport_bootstrap_grants x JOIN worker_transport_generations g ON g.id=x.generation_id WHERE g.workspace_id=w
 UNION ALL SELECT 'channel_history',x.id::text,to_jsonb(x) FROM worker_transport_history x WHERE x.workspace_id=w
 UNION ALL SELECT 'channel_head',x.workspace_id::text||':'||x.host_id::text,to_jsonb(x) FROM worker_transport_heads x WHERE x.workspace_id=w
 UNION ALL SELECT 'channel_audit',x.history_id::text,to_jsonb(x) FROM worker_transport_audit x JOIN worker_transport_history h ON h.id=x.history_id WHERE h.workspace_id=w
 UNION ALL SELECT 'bootstrap_head',x.workspace_id::text||':'||x.host_id::text,to_jsonb(x) FROM worker_bootstrap_heads x WHERE x.workspace_id=w
 UNION ALL SELECT 'bootstrap_audit',CASE WHEN x.history_id IS NULL THEN x.ticket_id::text||':issue' ELSE x.history_id::text||':consume' END,to_jsonb(x) FROM worker_bootstrap_audit x JOIN worker_bootstrap_tickets t ON t.id=x.ticket_id WHERE t.workspace_id=w
 UNION ALL SELECT 'decision_authority_event',x.decision_id::text||':'||x.revision::text,to_jsonb(x) FROM decision_authority_events x WHERE x.workspace_id=w
 UNION ALL SELECT 'v3_reservation',x.id::text,to_jsonb(x) FROM bootstrap_v3_operations x WHERE x.workspace_id=w
 UNION ALL SELECT 'v3_seal',x.attempt_id::text,to_jsonb(x) FROM bootstrap_v3_seals x WHERE x.workspace_id=w
 UNION ALL SELECT 'v3_seal_audit',x.id::text,to_jsonb(x) FROM bootstrap_v3_seal_audit x WHERE x.workspace_id=w
 ) SELECT coalesce(jsonb_agg(jsonb_build_object('source',role,'key',rkey,'digest',bootstrap_v3_native_digest(r),'bindingDigest',bootstrap_v3_binding(role,rkey,r,p)) ORDER BY convert_to(role||':'||rkey,'UTF8')),'[]') INTO rows FROM source;
 PERFORM bootstrap_v3_assert(jsonb_array_length(rows)<=1024 AND (SELECT count(DISTINCT (v->>'source',v->>'key')) FROM jsonb_array_elements(rows) v)=jsonb_array_length(rows),'source_set_size_or_duplicates');
 SELECT coalesce(jsonb_agg(jsonb_build_object('decisionId',d.id,'revision',h.revision::text,'digest',bootstrap_v3_native_digest(to_jsonb(h)),'fanout',d.authority_revision=1) ORDER BY convert_to(d.id::text,'UTF8')),'[]') INTO heads
 FROM decisions d JOIN decision_authority_events h ON h.decision_id=d.id
 WHERE d.workspace_id=w AND NOT EXISTS(SELECT 1 FROM decision_authority_events n WHERE n.decision_id=h.decision_id AND n.revision>h.revision);
 PERFORM bootstrap_v3_assert(jsonb_array_length(heads) BETWEEN 1 AND 32,'authority_heads');
 SELECT revision INTO f FROM ready_source_fence WHERE id=1;
 RETURN jsonb_build_object('coverage',jsonb_build_array('workspace','membership','decision','decision_revision','decision_acceptance','owner_auth','identity','host','issuer','attestation_key','anchor',
  'ticket','attempt','credential','handoff','ticket_lifecycle','bootstrap_history','dispatch','completion','proof_key','proof_attachment','proof_link','channel_generation','channel_grant','channel_history','channel_head','channel_audit',
  'bootstrap_head','bootstrap_audit','decision_authority_event','v3_reservation','v3_seal','v3_seal_audit'),'rows',rows,'heads',heads,
  'factsDigest',bootstrap_proof_digest(jsonb_build_array('roost-bootstrap-v3-protected-authority-v1',(p->'authority')-ARRAY['at','fence','writerXid','authorityRevision','authorityDigest','sourceDigest'])),
  'sourceSetDigest',bootstrap_proof_digest(jsonb_build_array('roost-bootstrap-v3-full-source-set-v1',rows)),'fence',f::text);
END $$;

CREATE FUNCTION bootstrap_v3_expected(op UUID,slot TEXT) RETURNS JSONB LANGUAGE plpgsql VOLATILE AS $$
DECLARE operation bootstrap_v3_operations;p JSONB;s JSONB;a JSONB;c JSONB;i JSONB;snap JSONB;r JSONB;ident JSONB;meta JSONB;spec JSONB;par JSONB;
 tbl TEXT;keys TEXT[]:=ARRAY['id'];atime TEXT;before worker_transport_history;life worker_bootstrap_lifecycle_events;
 history worker_bootstrap_history;head worker_transport_heads;authority decision_authority_events;f BIGINT;BEGIN
 SELECT * INTO operation FROM bootstrap_v3_operations WHERE id=op;
 PERFORM bootstrap_v3_assert(operation.id IS NOT NULL,'operation_missing');p:=operation.plan;s:=p->'authority';a:=s->'attachment';i:=s->'intent';
 c:=p->'envelope'->'signed'->'payload'->'context';snap:=c->'channel'->'snapshot';atime:=s->>'at';
 SELECT value INTO spec FROM jsonb_array_elements(bootstrap_v3_recipe(p,operation.anchor->'before'->'heads')) WHERE value->>'slot'=slot;
 PERFORM bootstrap_v3_assert(spec IS NOT NULL,'unknown_slot');
 IF spec->>'authorityFor' IS NOT NULL THEN
  tbl:='decision_authority_events';
  SELECT record INTO par FROM bootstrap_v3_mutations WHERE operation_id=op AND record->>'slot'=spec->>'parentSlot';
  SELECT * INTO authority FROM decision_authority_events WHERE decision_id=(spec->>'authorityFor')::uuid AND id<>bootstrap_v3_id(op,slot) ORDER BY revision DESC LIMIT 1;
  SELECT revision INTO f FROM ready_source_fence WHERE id=1;
  r:=jsonb_build_object('id',bootstrap_v3_id(op,slot),'workspace_id',operation.workspace_id,'decision_id',spec->'authorityFor',
   'revision',authority.revision+1,'action','source_change','source_table',bootstrap_v3_table(par->'after'->>'source'),'source_row',par->'after'->'key',
   'source_digest',par->'after'->'digest','previous_digest',authority.record_digest,'record_digest','','fence_revision',coalesce((SELECT revision FROM bootstrap_v3_epoch_claims WHERE operation_id=op AND bootstrap_v3_epoch_claims.slot=bootstrap_v3_expected.slot AND guard<>'statement_guard'),f+1),
   'writer_xid',operation.writer_xid,'at',atime,'mutation_digest',NULL);
 ELSE CASE slot
 WHEN 'reservation' THEN tbl:='bootstrap_v3_operations';r:=to_jsonb(operation);
 WHEN 'ticket' THEN
  tbl:='worker_bootstrap_tickets';
  meta:=jsonb_build_object('version','bootstrap-ticket-revocation-proposal-v1','ticketId',a->'ticketId','ticketDigest',p->'link'->'ticketEnvelopeDigest',
   'ownerId',a->'ownerId','decisionId',a->'decisionId','decisionRevision',a->'decisionRevision','purpose',a->'purpose','binding',i->'binding',
   'generation',a->'enrollmentGeneration','credentialEpoch',i->'target'->'epoch','issuedAt',s->'at','notBefore',s->'at','expiresAt',i->'expiresAt',
   'hostGeneration',a->'generation'->'hostGeneration','installationGeneration',a->'generation'->'installationGeneration','issuerRevision',s->'issuer'->'revision',
   'issuerHistoryDigest',s->'issuer'->'historyDigest','channelGeneration',snap->'generation','channelRevision',snap->'revision',
   'channelDigest',bootstrap_lifecycle_digest(jsonb_build_object('domain','worker-bootstrap-channel-plan-v2','snapshot',snap)),'predecessor',i->'prior');
  r:=jsonb_build_object('id',a->'ticketId','workspace_id',a->'workspaceId','host_id',a->'generation'->'hostId','owner_id',a->'ownerId',
   'decision_id',a->'decisionId','request_id',a->'requestId','generation',a->'enrollmentGeneration','credential_epoch',i->'target'->'epoch',
   'target_id',i->'target'->'id','predecessor_id',i->'prior'->'attemptId','binding_digest',bootstrap_lifecycle_digest(i->'binding'),
   'ticket_digest',p->'link'->'ticketEnvelopeDigest','record',(p->'envelope')-ARRAY['version','domain'],
   'record_digest',bootstrap_lifecycle_digest((p->'envelope')-ARRAY['version','domain']),'expires_at',i->'expiresAt','lifecycle_identity',meta);
 WHEN 'ticket-audit','attempt-audit' THEN
  tbl:='worker_bootstrap_audit';
  r:=jsonb_build_object('id',bootstrap_v3_id(op,slot),'ticket_id',a->'ticketId','history_id',CASE WHEN slot='attempt-audit' THEN c->'attemptHistoryId' ELSE 'null'::jsonb END,
   'event_id',bootstrap_v3_id(op,'projection-event:'||CASE WHEN slot='ticket-audit' THEN 'ticket' ELSE 'attempt-history' END||':lifecycle'),
   'record_digest',CASE WHEN slot='ticket-audit' THEN bootstrap_lifecycle_digest((p->'envelope')-ARRAY['version','domain']) ELSE
    (SELECT record_digest FROM worker_bootstrap_history WHERE id=(c->>'attemptHistoryId')::uuid) END);
 WHEN 'ticket-issue','ticket-consume' THEN
  tbl:='worker_bootstrap_lifecycle_events';
  IF slot='ticket-consume' THEN SELECT * INTO life FROM worker_bootstrap_lifecycle_events WHERE id=(c->>'issueEventId')::uuid;END IF;
  r:=jsonb_build_object('id',CASE WHEN slot='ticket-issue' THEN c->'issueEventId' ELSE c->'consumeEventId' END,'ticketId',a->'ticketId',
   'revision',CASE WHEN slot='ticket-issue' THEN 1 ELSE 2 END,'previousDigest',life.record_digest,'action',CASE WHEN slot='ticket-issue' THEN 'issue' ELSE 'consume' END,
   'state',CASE WHEN slot='ticket-issue' THEN 'issued' ELSE 'consumed' END,'attemptId',CASE WHEN slot='ticket-consume' THEN c->'attemptId' ELSE 'null'::jsonb END,
   'historyId',CASE WHEN slot='ticket-consume' THEN c->'attemptHistoryId' ELSE 'null'::jsonb END,'revoked',false,'expired',false,'reconciled',false,'at',atime);
  r:=jsonb_build_object('id',r->'id','ticket_id',a->'ticketId','revision',r->'revision','previous_digest',life.record_digest,'record',r,
   'record_digest',bootstrap_lifecycle_digest(r),'attempt_id',r->'attemptId','history_id',r->'historyId','writer_xid',operation.writer_xid);
 WHEN 'channel-generation' THEN
  tbl:='worker_transport_generations';ident:=jsonb_build_object('binding',i->'binding','hostGeneration',a->'generation'->'hostGeneration','installationGeneration',a->'generation'->'installationGeneration');
  r:=jsonb_build_object('id',snap->'generation','workspace_id',a->'workspaceId','host_id',a->'generation'->'hostId','installation_id',a->'installationId',
   'credential_id',NULL,'identity',ident,'identity_digest',bootstrap_lifecycle_digest(ident),'purpose',a->'purpose');
 WHEN 'channel-grant' THEN
  tbl:='worker_transport_bootstrap_grants';
  r:=jsonb_build_object('id',c->'channelGrantId','intent',jsonb_build_object('schemaVersion','worker-bootstrap-channel-v1','ticketId',a->'ticketId',
   'ticketDigest',p->'link'->'ticketEnvelopeDigest','expectedRevision',s->'channel'->'previousRevision','snapshot',snap),
   'ownerId',a->'ownerId','decisionId',a->'decisionId','decisionRevision',a->'decisionRevision','acceptanceId',s->'channel'->'acceptanceId','at',atime);
  r:=jsonb_build_object('id',c->'channelGrantId','generation_id',snap->'generation','purpose',a->'purpose','ticket_id',a->'ticketId',
   'decision_id',a->'decisionId','acceptance_id',s->'channel'->'acceptanceId','record',r,'record_digest',bootstrap_v3_native_digest(r));
 WHEN 'channel-history' THEN
  tbl:='worker_transport_history';
  SELECT * INTO head FROM worker_transport_heads WHERE workspace_id=operation.workspace_id AND host_id=(a->'generation'->>'hostId')::uuid;
  SELECT * INTO before FROM worker_transport_history WHERE id=head.history_id;
  r:=jsonb_build_object('id',c->'channelHistoryId','grantId',c->'channelGrantId','revision',snap->'revision','previousId',head.history_id,'action','grant','state','current','at',atime);
  r:=jsonb_build_object('id',c->'channelHistoryId','workspace_id',a->'workspaceId','host_id',a->'generation'->'hostId','generation_id',snap->'generation',
   'revision',snap->'revision','record_digest',bootstrap_v3_native_digest(r),'previous_revision',head.revision,'previous_digest',head.record_digest,
   'previous_high_water',head.high_water_epoch,'previous_state',head.state,'previous_generation_id',before.generation_id,
   'certificate_epoch',snap->'certificateEpoch','high_water_epoch',snap->'highWaterEpoch','state','current','request_id',bootstrap_v3_id(op,'channel-request'),
   'decision_id',a->'decisionId','decision_revision',a->'decisionRevision','decision_intent_digest',s->'owner'->'intentDigest','owner_id',a->'ownerId',
   'current_pin',snap->'leafPin','staged_pin',NULL,'record',r,'signature',NULL,'purpose',a->'purpose','writer_xid',operation.writer_xid);
 WHEN 'channel-head' THEN
  tbl:='worker_transport_heads';keys:=ARRAY['workspace_id','host_id'];SELECT * INTO before FROM worker_transport_history WHERE id=(c->>'channelHistoryId')::uuid;
  r:=jsonb_build_object('workspace_id',a->'workspaceId','host_id',a->'generation'->'hostId','history_id',before.id,'revision',before.revision,
   'record_digest',before.record_digest,'certificate_epoch',before.certificate_epoch,'high_water_epoch',before.high_water_epoch,'state',before.state,'purpose',before.purpose);
 WHEN 'channel-audit' THEN
  tbl:='worker_transport_audit';keys:=ARRAY['history_id'];
  r:=jsonb_build_object('history_id',c->'channelHistoryId','event_id',bootstrap_v3_id(op,'projection-event:channel-history:transport'),
   'record_digest',(SELECT record_digest FROM worker_transport_history WHERE id=(c->>'channelHistoryId')::uuid));
 WHEN 'attempt' THEN
  tbl:='worker_bootstrap_attempts';
  r:=jsonb_build_object('id',c->'attemptId','ticketId',a->'ticketId','ticketDigest',p->'link'->'ticketEnvelopeDigest','decisionId',a->'decisionId','requestId',a->'requestId',
   'binding',i->'binding','target',i->'target','state','consumed','expiresAt',i->'expiresAt');
  r:=jsonb_build_object('id',c->'attemptId','ticket_id',a->'ticketId','workspace_id',a->'workspaceId','host_id',a->'generation'->'hostId','generation',a->'enrollmentGeneration',
   'credential_epoch',i->'target'->'epoch','predecessor_id',i->'prior'->'attemptId','record',r,'record_digest',bootstrap_lifecycle_digest(r),
   'lifecycle_version','bootstrap-ticket-revocation-proposal-v1','attestation_id',NULL,'attestation_seal',NULL,'attestation_committed_at',NULL,'attestation_mutation_digest',NULL);
 WHEN 'attempt-history' THEN
  tbl:='worker_bootstrap_history';
  r:=jsonb_build_object('id',c->'attemptHistoryId','attemptId',c->'attemptId','revision',1,'previousDigest',NULL,'previousState',NULL,'state','consumed','createdAt',atime,'peer',NULL,'completion',NULL);
  r:=jsonb_build_object('id',c->'attemptHistoryId','attempt_id',c->'attemptId','revision',1,'state','consumed','record',r,'record_digest',bootstrap_lifecycle_digest(r),
   'previous_revision',NULL,'previous_digest',NULL,'previous_state',NULL);
 WHEN 'attempt-head' THEN
  tbl:='worker_bootstrap_heads';keys:=ARRAY['workspace_id','host_id'];SELECT * INTO history FROM worker_bootstrap_history WHERE id=(c->>'attemptHistoryId')::uuid;
  r:=jsonb_build_object('workspace_id',a->'workspaceId','host_id',a->'generation'->'hostId','attempt_id',c->'attemptId','history_id',history.id,
   'generation',a->'enrollmentGeneration','credential_epoch',i->'target'->'epoch','revision',1,'record_digest',history.record_digest,'state','consumed');
 WHEN 'proof-link' THEN
  tbl:='bootstrap_proof_ticket_links';
  r:=jsonb_build_object('id',c->'linkId','attachment_id',s->'attachmentId','ticket_id',a->'ticketId','attempt_id',c->'attemptId','workspace_id',a->'workspaceId',
   'host_id',a->'generation'->'hostId','enrollment_generation',a->'enrollmentGeneration','record',p->'link',
   'record_bytes','\x'||encode(bootstrap_proof_bytes(p->'link',0),'hex'),'record_digest',bootstrap_proof_digest(p->'link'),
   'source_digest',bootstrap_proof_sources(operation.workspace_id),'writer_xid',operation.writer_xid);
 WHEN 'attempt-seal' THEN
  tbl:='bootstrap_v3_seals';keys:=ARRAY['attempt_id'];r:=jsonb_build_object('attempt_id',c->'attemptId','operation_id',op,'workspace_id',operation.workspace_id,'record',p->'seal');
 WHEN 'seal-audit' THEN
  tbl:='bootstrap_v3_seal_audit';r:=jsonb_build_object('id',c->'receiptEventId','operation_id',op,'workspace_id',operation.workspace_id,'attempt_id',c->'attemptId','record',spec->'binding');
 ELSE RAISE EXCEPTION 'bootstrap_v3_unknown_slot';END CASE;END IF;
 EXECUTE format('SELECT to_jsonb(jsonb_populate_record(NULL::public.%I,$1))',tbl) INTO r USING r;
 IF tbl='decision_authority_events' THEN r:=r||jsonb_build_object('record_digest',decision_attestation_digest('owner-decision-authority-event-v1',r-'record_digest'));END IF;
 RETURN jsonb_build_object('table',tbl,'keys',keys,'row',r,'spec',spec);
END $$;

CREATE FUNCTION bootstrap_v3_active() RETURNS UUID LANGUAGE plpgsql VOLATILE AS $$
BEGIN RETURN (SELECT id FROM bootstrap_v3_operations WHERE writer_xid=pg_current_xact_id()::text);END $$;
CREATE FUNCTION bootstrap_v3_next(op UUID) RETURNS JSONB LANGUAGE plpgsql VOLATILE AS $$
DECLARE o bootstrap_v3_operations;n INT;BEGIN
 SELECT * INTO o FROM bootstrap_v3_operations WHERE id=op;
 SELECT count(*) INTO n FROM bootstrap_v3_mutations WHERE operation_id=op;
 RETURN bootstrap_v3_recipe(o.plan,o.anchor->'before'->'heads')->n;
END $$;
CREATE FUNCTION bootstrap_v3_root(op UUID,slot TEXT) RETURNS TEXT LANGUAGE plpgsql VOLATILE AS $$
DECLARE o bootstrap_v3_operations;spec JSONB;parent TEXT;BEGIN
 SELECT * INTO o FROM bootstrap_v3_operations WHERE id=op;
 SELECT value INTO spec FROM jsonb_array_elements(bootstrap_v3_recipe(o.plan,o.anchor->'before'->'heads')) x WHERE x->>'slot'=slot;
 PERFORM bootstrap_v3_assert(spec IS NOT NULL,'unknown_causal_root');parent:=spec->>'parentSlot';
 RETURN CASE WHEN parent IS NULL THEN slot ELSE bootstrap_v3_root(op,parent) END;
END $$;
CREATE FUNCTION bootstrap_v3_advance(op UUID,slot TEXT,guard_role TEXT) RETURNS BIGINT LANGUAGE plpgsql VOLATILE AS $$
DECLARE f BIGINT;spec JSONB;BEGIN
 PERFORM bootstrap_v3_assert(pg_trigger_depth()>0 AND op=bootstrap_v3_active(),'automatic_epoch_required');
 f:=bootstrap_v3_mode(true);spec:=bootstrap_v3_next(op);
 PERFORM bootstrap_v3_assert(spec->>'slot'=slot AND guard_role=CASE WHEN guard_role='statement_guard' THEN 'statement_guard'
  WHEN spec->>'parentSlot' IS NULL THEN 'row_guard' ELSE 'nested_guard' END,'epoch_driver');
 INSERT INTO bootstrap_v3_epoch_claims(revision,operation_id,writer_xid,slot,guard)
 VALUES(f+1,op,pg_current_xact_id()::text,slot,guard_role);
 UPDATE ready_source_fence SET revision=revision+1 WHERE id=1 RETURNING revision INTO f;RETURN f;
END $$;
CREATE FUNCTION bootstrap_v3_epoch_observe() RETURNS TRIGGER LANGUAGE plpgsql AS $$
DECLARE claim bootstrap_v3_epoch_claims;o bootstrap_v3_operations;eid UUID:=gen_random_uuid();BEGIN
 IF NEW.revision=OLD.revision THEN RETURN NULL;END IF;
 PERFORM bootstrap_v3_assert(TG_OP='UPDATE' AND NEW.id=1 AND OLD.id=1 AND NEW.revision=OLD.revision+1
  AND current_setting('session_replication_role')='origin','noncontiguous_native_fence');
 SELECT * INTO claim FROM bootstrap_v3_epoch_claims WHERE revision=NEW.revision AND writer_xid=pg_current_xact_id()::text;
 SELECT * INTO o FROM bootstrap_v3_operations WHERE id=claim.operation_id;
 INSERT INTO events(id,workspace_id,type,source,actor_type,resource_type,resource_id,payload,updated_at)
 VALUES(eid,o.workspace_id,'bootstrap.v3.epoch','roost','system','ready_source_fence','1',
  jsonb_build_object('revision',NEW.revision::text,'previousRevision',OLD.revision::text,'writerXid',pg_current_xact_id()::text,
   'operationId',claim.operation_id,'slot',claim.slot,'guard',claim.guard,'launchAuthority',false),clock_timestamp());
 INSERT INTO bootstrap_v3_epochs(revision,previous_revision,writer_xid,operation_id,slot,guard,event_id)
 VALUES(NEW.revision,OLD.revision,pg_current_xact_id()::text,claim.operation_id,claim.slot,claim.guard,eid);RETURN NULL;
END $$;

CREATE FUNCTION bootstrap_v3_guard(tbl TEXT,action TEXT,new_row JSONB,old_row JSONB) RETURNS JSONB LANGUAGE plpgsql VOLATILE AS $$
DECLARE op UUID:=bootstrap_v3_active();expected JSONB;spec JSONB;prior JSONB;f BIGINT;BEGIN
 PERFORM bootstrap_v3_assert(op IS NOT NULL AND pg_trigger_depth()>0,'v3_writer_required');
 spec:=bootstrap_v3_next(op);expected:=bootstrap_v3_expected(op,spec->>'slot');
 PERFORM bootstrap_v3_assert(expected->>'table'=tbl AND action IN ('INSERT','UPDATE')
  AND (action='INSERT' OR spec->>'update'='true')
  AND new_row-'previous_generation'=(expected->'row')-'previous_generation','exact_native_row');
 IF action='UPDATE' THEN
  SELECT value INTO prior FROM jsonb_array_elements((SELECT anchor->'before'->'rows' FROM bootstrap_v3_operations WHERE id=op))
  WHERE value->>'source'=spec->>'source' AND value->>'key'=spec->>'key';
  PERFORM bootstrap_v3_assert(prior->>'digest'=bootstrap_v3_native_digest(old_row)
   AND bootstrap_v3_native_digest(old_row)<>bootstrap_v3_native_digest(new_row),'head_preimage');
 END IF;
 f:=bootstrap_v3_advance(op,spec->>'slot',CASE WHEN spec->>'parentSlot' IS NULL THEN 'row_guard' ELSE 'nested_guard' END);
 RETURN new_row;
END $$;

CREATE FUNCTION bootstrap_v3_capture(tbl TEXT,action TEXT,new_row JSONB,old_row JSONB) RETURNS VOID LANGUAGE plpgsql VOLATILE AS $$
DECLARE op UUID:=bootstrap_v3_active();o bootstrap_v3_operations;expected JSONB;spec JSONB;par JSONB;change JSONB:='null';
 previous TEXT;body JSONB;after_row JSONB;mutation UUID;epoch BIGINT;seq BIGINT;family TEXT;eid UUID;rid UUID;parent_receipt UUID;
 native_key TEXT;native_digest TEXT;native_receipt JSONB;native_event JSONB;normalized JSONB;receipt_body JSONB;ident TEXT;head decision_authority_events;BEGIN
 SELECT * INTO o FROM bootstrap_v3_operations WHERE id=op;
 PERFORM bootstrap_v3_assert(o.id IS NOT NULL AND pg_trigger_depth()>0 AND o.writer_xid=pg_current_xact_id()::text,'automatic_mutation_required');
 spec:=bootstrap_v3_next(op);expected:=bootstrap_v3_expected(op,spec->>'slot');
 PERFORM bootstrap_v3_assert(expected->>'table'=tbl AND new_row-'previous_generation'=(expected->'row')-'previous_generation','captured_native_row');
 IF spec->>'slot'='reservation' THEN PERFORM bootstrap_v3_advance(op,'reservation','row_guard');END IF;
 SELECT revision INTO epoch FROM ready_source_fence WHERE id=1;
 PERFORM bootstrap_v3_assert(EXISTS(SELECT 1 FROM bootstrap_v3_epochs WHERE revision=epoch AND operation_id=op AND slot=spec->>'slot' AND guard<>'statement_guard'),'mutation_epoch');
 mutation:=bootstrap_v3_id(op,'projection:mutation:'||(spec->>'slot'));
 SELECT record INTO par FROM bootstrap_v3_mutations WHERE operation_id=op AND record->>'slot'=spec->>'parentSlot';
 IF spec->>'authorityFor' IS NOT NULL THEN
  SELECT * INTO head FROM decision_authority_events WHERE decision_id=(spec->>'authorityFor')::uuid AND id<>(new_row->>'id')::uuid ORDER BY revision DESC LIMIT 1;
  change:=jsonb_build_object('decisionId',spec->'authorityFor','revision',new_row->>'revision','previousDigest',bootstrap_v3_native_digest(to_jsonb(head)),
   'action','source_change','source',par->'after'->'source','sourceKey',par->'after'->'key','sourceDigest',par->'after'->'digest','causeMutationId',par->'id');
  spec:=spec||jsonb_build_object('key',spec->>'authorityFor'||':'||(new_row->>'revision'),'binding',change);
 END IF;
 after_row:=jsonb_build_object('source',spec->'source','key',spec->'key','digest',bootstrap_v3_native_digest(new_row),'bindingDigest',bootstrap_proof_digest(spec->'binding'));
 SELECT record->>'digest' INTO previous FROM bootstrap_v3_mutations WHERE operation_id=op ORDER BY sequence DESC LIMIT 1;
 body:=jsonb_build_object('id',mutation,'slot',spec->'slot','phase',spec->'phase','operationId',op,'writerXid',o.writer_xid,'epoch',epoch::text,
  'parentId',par->'id','beforeDigest',CASE WHEN action='UPDATE' THEN bootstrap_v3_native_digest(old_row) ELSE NULL END,'after',after_row,'authorityChange',change,
  'previousDigest',coalesce(previous,o.anchor->>'digest'));
 body:=body||jsonb_build_object('digest',bootstrap_proof_digest(jsonb_build_array('roost-bootstrap-v3-mutation-v1',body)));
 INSERT INTO bootstrap_v3_mutations(operation_id,writer_xid,epoch,table_name,row_key,before_digest,after_digest,record)
 VALUES(op,o.writer_xid,epoch,tbl,spec->>'key',body->>'beforeDigest',after_row->>'digest',body) RETURNING sequence INTO seq;
 FOR family IN SELECT jsonb_array_elements_text(spec->'families') LOOP
  eid:=bootstrap_v3_id(op,'projection-event:'||(spec->>'slot')||':'||family);rid:=bootstrap_v3_id(op,'projection:receipt:'||(spec->>'slot')||':'||family);
  parent_receipt:=NULL;
  IF par IS NOT NULL THEN
   SELECT id INTO parent_receipt FROM bootstrap_v3_receipts WHERE operation_id=op AND record->>'subjectId'=par->>'id'
   ORDER BY CASE WHEN bootstrap_v3_receipts.family='attestation' THEN 0 ELSE 1 END,id LIMIT 1;
   PERFORM bootstrap_v3_assert(parent_receipt IS NOT NULL,'parent_receipt');
  END IF;
  ident:=CASE WHEN tbl IN ('worker_bootstrap_heads','worker_transport_heads') THEN new_row->>'workspace_id'||':'||(new_row->>'host_id') ELSE coalesce(new_row->>'id',new_row->>'history_id',new_row->>'attempt_id') END;
  IF family='lifecycle' THEN
   INSERT INTO events(id,workspace_id,type,source,actor_type,actor_id,resource_type,resource_id,payload,updated_at)
   VALUES(eid,o.workspace_id,'worker.bootstrap_lifecycle','roost','user',o.plan->'authority'->'attachment'->>'ownerId',tbl,ident,
    jsonb_build_object('ticketId',o.plan->'authority'->'attachment'->'ticketId','rowDigest',after_row->'digest','fence',epoch::text,'writerXid',o.writer_xid,'launchAuthority',false),clock_timestamp());
   INSERT INTO worker_bootstrap_write_receipts(ticket_id,table_name,row_id,writer_xid,row_digest,fence_revision,event_id)
   VALUES((o.plan->'authority'->'attachment'->>'ticketId')::uuid,tbl,ident,o.writer_xid,after_row->>'digest',epoch,eid) RETURNING to_jsonb(worker_bootstrap_write_receipts.*) INTO native_receipt;
   native_key:='lifecycle:'||eid::text;
  ELSIF family='attestation' THEN
   ident:=coalesce(new_row->>'id',new_row->>'decision_id',new_row->>'workspace_id')||coalesce(':'||(new_row->>'host_id'),'');
   INSERT INTO events(id,workspace_id,type,source,actor_type,resource_type,resource_id,payload,updated_at)
   VALUES(eid,o.workspace_id,'decision.attestation.write','roost','system',tbl,ident,jsonb_build_object('table',tbl,'rowId',ident,'operation',action,'rowDigest',after_row->'digest','fence',epoch::text,'writerXid',o.writer_xid,'launchAuthority',false),clock_timestamp());
   INSERT INTO decision_attestation_write_receipts(id,workspace_id,table_name,row_id,operation,row_digest,fence_revision,writer_xid,event_id)
   VALUES(rid,o.workspace_id,tbl,ident,action,after_row->>'digest',epoch,o.writer_xid,eid) RETURNING to_jsonb(decision_attestation_write_receipts.*) INTO native_receipt;
   native_key:='attestation:'||rid::text;
  ELSIF family='transport' THEN
   INSERT INTO events(id,workspace_id,type,source,actor_type,resource_type,resource_id,payload,updated_at)
   VALUES(eid,o.workspace_id,'bootstrap.v3.transport','roost','system',tbl,ident,jsonb_build_object('table',tbl,'rowId',ident,'rowDigest',after_row->'digest','fence',epoch::text,'writerXid',o.writer_xid,'launchAuthority',false),clock_timestamp());
   INSERT INTO worker_transport_write_audit(generation_id,table_name,row_id,writer_xid,row_digest,fence_revision)
   VALUES((o.plan->'authority'->'channel'->'snapshot'->>'generation')::uuid,tbl,ident,o.writer_xid,after_row->>'digest',epoch) RETURNING to_jsonb(worker_transport_write_audit.*) INTO native_receipt;
   native_key:='transport:'||rid::text;
  ELSIF family='proof' THEN
   INSERT INTO events(id,workspace_id,type,source,actor_type,resource_type,resource_id,payload,updated_at)
   VALUES(eid,o.workspace_id,'bootstrap.proof_authority','roost','system',tbl,ident,
    jsonb_build_object('operationId',new_row->'id','table',tbl,'digest',new_row->'record_digest','sourceDigest',new_row->'source_digest',
     'writerXid',o.writer_xid,'fromFence',(epoch-1)::text,'toFence',epoch::text,'launchAuthority',false),clock_timestamp());
   INSERT INTO bootstrap_proof_write_receipts(operation_id,link_operation,event_id,table_name,record_digest,source_digest,writer_xid,from_fence,to_fence)
   VALUES((new_row->>'id')::uuid,(new_row->>'id')::uuid,eid,tbl,new_row->>'record_digest',new_row->>'source_digest',o.writer_xid,epoch-1,epoch)
   RETURNING to_jsonb(bootstrap_proof_write_receipts.*) INTO native_receipt;
   native_key:='proof:'||(new_row->>'id');
  ELSE
   INSERT INTO events(id,workspace_id,type,source,actor_type,resource_type,resource_id,payload,updated_at)
   VALUES(eid,o.workspace_id,'bootstrap.v3.projection','roost','system',tbl,ident,
    jsonb_build_object('operationId',op,'slot',spec->'slot','rowDigest',after_row->'digest','fence',epoch::text,'writerXid',o.writer_xid,'launchAuthority',false),clock_timestamp());
   -- The immutable mutation itself is the native projection receipt subject.
   SELECT to_jsonb(m) INTO native_receipt FROM bootstrap_v3_mutations m WHERE sequence=seq;native_key:='projection:'||seq::text;
  END IF;
  SELECT to_jsonb(ev) INTO native_event FROM events ev WHERE id=eid;
  normalized:=jsonb_build_object('id',eid,'workspaceId',o.workspace_id,'operationId',op,'writerXid',o.writer_xid,'phase',spec->'phase','epoch',epoch::text,
   'receiptId',rid,'subjectId',mutation,'subjectDigest',after_row->'digest','family',family,'source',spec->'source','key',spec->'key','parentReceiptId',parent_receipt,'launchAuthority',false);
  native_digest:=bootstrap_v3_native_digest(native_receipt);
  receipt_body:=jsonb_build_object('id',rid,'subjectId',mutation,'family',family,'operationId',op,'writerXid',o.writer_xid,'phase',spec->'phase','epoch',epoch::text,
   'rowDigest',after_row->'digest','parentReceiptId',parent_receipt,'nativeReceiptKey',native_key,'nativeReceiptDigest',native_digest,
   'nativeEventDigest',bootstrap_v3_native_digest(native_event),'event',normalized,'eventDigest',bootstrap_proof_digest(normalized));
  receipt_body:=receipt_body||jsonb_build_object('digest',bootstrap_proof_digest(jsonb_build_array('roost-bootstrap-v3-receipt-v1',receipt_body)));
  INSERT INTO bootstrap_v3_receipts(id,operation_id,mutation_sequence,family,event_id,native_table,native_key,native_digest,record)
  VALUES(rid,op,seq,family,eid,CASE family WHEN 'lifecycle' THEN 'worker_bootstrap_write_receipts' WHEN 'attestation' THEN 'decision_attestation_write_receipts'
   WHEN 'transport' THEN 'worker_transport_write_audit' WHEN 'proof' THEN 'bootstrap_proof_write_receipts' ELSE 'bootstrap_v3_mutations' END,native_key,native_digest,receipt_body);
 END LOOP;
END $$;

CREATE FUNCTION bootstrap_v3_insert(op UUID,slot TEXT) RETURNS VOID LANGUAGE plpgsql VOLATILE AS $$
DECLARE v JSONB:=bootstrap_v3_expected(op,slot);tbl TEXT:=v->>'table';cols TEXT;selects TEXT;assignments TEXT;predicate TEXT;present BOOLEAN;counted BIGINT;BEGIN
 PERFORM bootstrap_v3_assert(op=bootstrap_v3_active() AND bootstrap_v3_next(op)->>'slot'=slot
  AND tbl=bootstrap_v3_table(v->'spec'->>'source') AND slot<>'reservation','writer_slot');
 SELECT string_agg(format('%I',a.attname),',' ORDER BY a.attnum),string_agg(format('r.%I',a.attname),',' ORDER BY a.attnum),
  string_agg(format('%I=r.%I',a.attname,a.attname),',' ORDER BY a.attnum)
 INTO cols,selects,assignments FROM pg_attribute a
 WHERE a.attrelid=to_regclass('public.'||tbl) AND a.attnum>0 AND NOT a.attisdropped AND a.attgenerated='';
 SELECT string_agg(format('x.%I=r.%I',k,k),' AND ') INTO predicate FROM jsonb_array_elements_text(v->'keys') k;
 IF v->'spec'->>'update'='true' THEN
  EXECUTE format('SELECT EXISTS(SELECT 1 FROM public.%I x CROSS JOIN jsonb_populate_record(NULL::public.%I,$1) r WHERE %s)',tbl,tbl,predicate) INTO present USING v->'row';
 ELSE present:=false;END IF;
 IF present THEN
  EXECUTE format('UPDATE public.%I x SET %s FROM jsonb_populate_record(NULL::public.%I,$1) r WHERE %s',tbl,assignments,tbl,predicate) USING v->'row';
 ELSE
  EXECUTE format('INSERT INTO public.%I(%s) SELECT %s FROM jsonb_populate_record(NULL::public.%I,$1) r',tbl,cols,selects,tbl) USING v->'row';
 END IF;GET DIAGNOSTICS counted=ROW_COUNT;
 PERFORM bootstrap_v3_assert(counted=1,'writer_cardinality');
END $$;
CREATE FUNCTION bootstrap_v3_after(tbl TEXT,new_row JSONB) RETURNS VOID LANGUAGE plpgsql VOLATILE AS $$
DECLARE op UUID:=bootstrap_v3_active();m JSONB;next_spec JSONB;slot TEXT;BEGIN
 SELECT record INTO m FROM bootstrap_v3_mutations WHERE operation_id=op AND table_name=tbl AND after_digest=bootstrap_v3_native_digest(new_row);
 PERFORM bootstrap_v3_assert(m IS NOT NULL,'automatic_parent');slot:=m->>'slot';
 LOOP
  next_spec:=bootstrap_v3_next(op);
  EXIT WHEN next_spec->>'authorityFor' IS NULL OR next_spec->>'parentSlot' IS DISTINCT FROM slot;
  PERFORM bootstrap_v3_insert(op,next_spec->>'slot');
 END LOOP;
 CASE slot
 WHEN 'ticket' THEN PERFORM bootstrap_v3_insert(op,'ticket-audit');
 WHEN 'channel-history' THEN PERFORM bootstrap_v3_insert(op,'channel-head');PERFORM bootstrap_v3_insert(op,'channel-audit');
 WHEN 'attempt-history' THEN PERFORM bootstrap_v3_insert(op,'attempt-head');PERFORM bootstrap_v3_insert(op,'attempt-audit');
 WHEN 'attempt-seal' THEN PERFORM bootstrap_v3_insert(op,'seal-audit');
 ELSE NULL;END CASE;
END $$;

CREATE FUNCTION bootstrap_v3_native_receipt(r bootstrap_v3_receipts) RETURNS JSONB LANGUAGE plpgsql VOLATILE AS $$
DECLARE m bootstrap_v3_mutations;v JSONB;BEGIN
 SELECT * INTO m FROM bootstrap_v3_mutations WHERE sequence=r.mutation_sequence;
 CASE r.native_table
 WHEN 'worker_bootstrap_write_receipts' THEN SELECT to_jsonb(x) INTO v FROM worker_bootstrap_write_receipts x WHERE event_id=r.event_id;
 WHEN 'decision_attestation_write_receipts' THEN SELECT to_jsonb(x) INTO v FROM decision_attestation_write_receipts x WHERE event_id=r.event_id;
 WHEN 'worker_transport_write_audit' THEN SELECT to_jsonb(x) INTO v FROM worker_transport_write_audit x WHERE table_name=m.table_name AND writer_xid=m.writer_xid AND row_digest=m.after_digest;
 WHEN 'bootstrap_proof_write_receipts' THEN SELECT to_jsonb(x) INTO v FROM bootstrap_proof_write_receipts x WHERE event_id=r.event_id;
 WHEN 'bootstrap_v3_mutations' THEN v:=to_jsonb(m);
 ELSE RAISE EXCEPTION 'bootstrap_v3_unknown_receipt';END CASE;
 PERFORM bootstrap_v3_assert(v IS NOT NULL AND bootstrap_v3_native_digest(v)=r.native_digest
  AND r.native_digest=r.record->>'nativeReceiptDigest','native_receipt_changed');RETURN v;
END $$;

CREATE FUNCTION bootstrap_v3_evidence(op UUID,through_phase TEXT,observed_frame JSONB) RETURNS JSONB LANGUAGE plpgsql VOLATILE AS $$
DECLARE o bootstrap_v3_operations;lo BIGINT;hi BIGINT;mutations JSONB;receipts JSONB;epochs JSONB:='[]';w bootstrap_v3_epochs;ev JSONB;
 claim bootstrap_v3_epoch_claims;body JSONB;previous TEXT;driver UUID;root UUID;members JSONB;rs JSONB;phase TEXT;r bootstrap_v3_receipts;BEGIN
 SELECT * INTO o FROM bootstrap_v3_operations WHERE id=op;lo:=o.from_fence;hi:=(observed_frame->>'fence')::bigint;previous:=o.anchor->>'digest';
 -- Deliberately no workspace, operation or writer filter on the interval.
 SELECT coalesce(jsonb_agg(record ORDER BY sequence),'[]') INTO mutations FROM bootstrap_v3_mutations WHERE epoch>lo AND epoch<=hi;
 SELECT coalesce(jsonb_agg(r.record ORDER BY convert_to(r.id::text,'UTF8')),'[]') INTO receipts
 FROM bootstrap_v3_receipts r JOIN bootstrap_v3_mutations m ON m.sequence=r.mutation_sequence WHERE m.epoch>lo AND m.epoch<=hi;
 FOR r IN SELECT r.* FROM bootstrap_v3_receipts r JOIN bootstrap_v3_mutations m ON m.sequence=r.mutation_sequence WHERE m.epoch>lo AND m.epoch<=hi LOOP
  PERFORM bootstrap_v3_native_receipt(r);SELECT to_jsonb(e) INTO ev FROM events e WHERE id=r.event_id;
  PERFORM bootstrap_v3_assert(bootstrap_v3_native_digest(ev)=r.record->>'nativeEventDigest','native_event_changed');
 END LOOP;
 FOR w IN SELECT * FROM bootstrap_v3_epochs WHERE revision>lo AND revision<=hi ORDER BY revision LOOP
  SELECT * INTO claim FROM bootstrap_v3_epoch_claims WHERE revision=w.revision;
  SELECT to_jsonb(e) INTO ev FROM events e WHERE id=w.event_id;
  IF w.operation_id IS NULL THEN
   -- Unclaimed/foreign evidence remains visible and fails the closed projector.
   epochs:=epochs||jsonb_build_array(jsonb_build_object('unclaimedNativeEpoch',to_jsonb(w),'eventDigest',bootstrap_v3_native_digest(ev)));CONTINUE;
  END IF;
  driver:=bootstrap_v3_id(w.operation_id,'projection:mutation:'||w.slot);
  root:=bootstrap_v3_id(w.operation_id,'projection:mutation:'||bootstrap_v3_root(w.operation_id,w.slot));
  SELECT value->>'phase' INTO phase FROM jsonb_array_elements((SELECT bootstrap_v3_recipe(plan,anchor->'before'->'heads') FROM bootstrap_v3_operations WHERE id=w.operation_id)) WHERE value->>'slot'=w.slot;
  SELECT coalesce(jsonb_agg(record->'id' ORDER BY sequence),'[]') INTO members FROM bootstrap_v3_mutations WHERE epoch=w.revision;
  SELECT coalesce(jsonb_agg(r.id ORDER BY convert_to(r.id::text,'UTF8')),'[]') INTO rs FROM bootstrap_v3_receipts r JOIN bootstrap_v3_mutations m ON m.sequence=r.mutation_sequence WHERE m.epoch=w.revision;
  body:=jsonb_build_object('id',w.event_id,'operationId',w.operation_id,'writerXid',w.writer_xid,'phase',phase,'revision',w.revision::text,
   'driverId',driver,'rootId',root,'nativeReceiptKey','fence:'||w.revision::text,'nativeReceiptDigest',bootstrap_v3_native_digest(to_jsonb(w)),
   'nativeEventDigest',bootstrap_v3_native_digest(ev),'guard',w.guard,'members',members,'receipts',rs,'memberCount',jsonb_array_length(members),
   'receiptCount',jsonb_array_length(rs),'eventCount',jsonb_array_length(rs),'previousDigest',previous);
  body:=body||jsonb_build_object('digest',bootstrap_proof_digest(jsonb_build_array('roost-bootstrap-v3-epoch-v1',body)));
  previous:=body->>'digest';epochs:=epochs||jsonb_build_array(body);
 END LOOP;
 RETURN jsonb_build_object('version','bootstrap-v3-projection-evidence-v1','anchorDigest',o.anchor->'digest','through',through_phase,'mutations',mutations,'receipts',receipts,'epochs',epochs,'after',observed_frame);
END $$;

CREATE FUNCTION bootstrap_v3_check(op UUID,through_phase TEXT) RETURNS JSONB LANGUAGE plpgsql VOLATILE AS $$
DECLARE o bootstrap_v3_operations;frame JSONB;recipe JSONB;ev JSONB;rows JSONB;heads JSONB;spec JSONB;m JSONB;old JSONB;h JSONB;
 index INT:=0;limit_phase INT;last_epoch BIGINT;counted INT;epoch_row JSONB;driver JSONB;root UUID;rs JSONB;mem JSONB;BEGIN
 SELECT * INTO o FROM bootstrap_v3_operations WHERE id=op;
 PERFORM bootstrap_v3_assert(o.writer_xid=pg_current_xact_id()::text,'writer_identity');
 PERFORM bootstrap_v3_mode(true);
 PERFORM bootstrap_v3_assert((o.plan->'authority'->'intent'->>'expiresAt')::timestamptz>clock_timestamp()
  AND (o.plan->'authority'->'owner'->>'authenticatedAt')::timestamptz>=clock_timestamp()-interval '5 minutes'
  AND (o.plan->'authority'->'issuer'->>'expiresAt')::timestamptz>clock_timestamp()
  AND (o.plan->'authority'->'channel'->'snapshot'->'cutoverAt'='null' OR (o.plan->'authority'->'channel'->'snapshot'->>'cutoverAt')::timestamptz>clock_timestamp()),'authority_expired');
 PERFORM bootstrap_proof_reference(o.workspace_id,o.plan->'authority'->'attachment'->'worker',clock_timestamp(),o.plan->'authority'->'attachment'->'generation');
 PERFORM bootstrap_proof_reference(o.workspace_id,o.plan->'authority'->'attachment'->'server',clock_timestamp(),'null');
 limit_phase:=array_position(ARRAY['reservation','ticket','channel','attempt','link','seal'],through_phase);
 PERFORM bootstrap_v3_assert(limit_phase IS NOT NULL,'phase');
 frame:=bootstrap_v3_inventory(o.plan);recipe:=bootstrap_v3_recipe(o.plan,o.anchor->'before'->'heads');
 ev:=bootstrap_v3_evidence(op,through_phase,frame);rows:=o.anchor->'before'->'rows';heads:=o.anchor->'before'->'heads';last_epoch:=o.from_fence;
 FOR spec IN SELECT value FROM jsonb_array_elements(recipe) WHERE array_position(ARRAY['reservation','ticket','channel','attempt','link','seal'],value->>'phase')<=limit_phase LOOP
  m:=ev->'mutations'->index;index:=index+1;
  PERFORM bootstrap_v3_assert(m->>'slot'=spec->>'slot' AND m->>'operationId'=op::text AND m->>'writerXid'=o.writer_xid
   AND m->>'phase'=spec->>'phase' AND (m->>'epoch')::bigint>=last_epoch AND (m->>'epoch')::bigint>o.from_fence,'closed_mutation_recipe');
  last_epoch:=(m->>'epoch')::bigint;
  SELECT value INTO old FROM jsonb_array_elements(rows) WHERE value->>'source'=m->'after'->>'source' AND value->>'key'=m->'after'->>'key';
  PERFORM bootstrap_v3_assert(m->'beforeDigest'=coalesce(old->'digest','null') AND (old IS NULL OR spec->>'update'='true')
   AND old->>'digest' IS DISTINCT FROM m->'after'->>'digest','exact_preimage');
  SELECT coalesce(jsonb_agg(value),'[]') INTO rows FROM jsonb_array_elements(rows) WHERE NOT(value->>'source'=m->'after'->>'source' AND value->>'key'=m->'after'->>'key');
  rows:=rows||jsonb_build_array(m->'after');
  IF spec->>'authorityFor' IS NOT NULL THEN
   SELECT value INTO h FROM jsonb_array_elements(heads) WHERE value->>'decisionId'=spec->>'authorityFor';
   PERFORM bootstrap_v3_assert(m->'authorityChange'->>'previousDigest'=h->>'digest'
    AND (m->'authorityChange'->>'revision')::bigint=(h->>'revision')::bigint+1,'authority_lineage');
   SELECT jsonb_agg(CASE WHEN value->>'decisionId'=spec->>'authorityFor' THEN value||jsonb_build_object('revision',m->'authorityChange'->'revision','digest',m->'after'->'digest') ELSE value END) INTO heads FROM jsonb_array_elements(heads);
  END IF;
  SELECT count(*) INTO counted FROM jsonb_array_elements(ev->'receipts') r WHERE r->>'subjectId'=m->>'id';
  PERFORM bootstrap_v3_assert(counted=jsonb_array_length(spec->'families'),'receipt_completeness');
 END LOOP;
 PERFORM bootstrap_v3_assert(index=jsonb_array_length(ev->'mutations'),'extra_or_foreign_mutation');
 SELECT jsonb_agg(value ORDER BY convert_to(value->>'source'||':'||(value->>'key'),'UTF8')) INTO rows FROM jsonb_array_elements(rows);
 SELECT jsonb_agg(value ORDER BY convert_to(value->>'decisionId','UTF8')) INTO heads FROM jsonb_array_elements(heads);
 PERFORM bootstrap_v3_assert(rows=frame->'rows' AND heads=frame->'heads' AND frame->'factsDigest'=o.anchor->'before'->'factsDigest','full_source_drift');
 last_epoch:=o.from_fence;
 FOR epoch_row IN SELECT value FROM jsonb_array_elements(ev->'epochs') LOOP
  PERFORM bootstrap_v3_assert(epoch_row->>'operationId'=op::text AND epoch_row->>'writerXid'=o.writer_xid
   AND (epoch_row->>'revision')::bigint=last_epoch+1,'foreign_or_missing_epoch');last_epoch:=last_epoch+1;
  SELECT value INTO driver FROM jsonb_array_elements(ev->'mutations') WHERE value->>'id'=epoch_row->>'driverId';
  PERFORM bootstrap_v3_assert(driver IS NOT NULL AND driver->'phase'=epoch_row->'phase','epoch_driver_missing');
  FOR m IN SELECT value FROM jsonb_array_elements(ev->'mutations') WHERE value->'epoch'=epoch_row->'revision' LOOP
   root:=bootstrap_v3_id(op,'projection:mutation:'||bootstrap_v3_root(op,m->>'slot'));
   PERFORM bootstrap_v3_assert(root::text=epoch_row->>'rootId','borrowed_epoch_root');
  END LOOP;
  PERFORM bootstrap_v3_assert(CASE WHEN epoch_row->>'guard'='statement_guard' THEN jsonb_array_length(epoch_row->'members')=0 AND jsonb_array_length(epoch_row->'receipts')=0
    AND (driver->>'epoch')::bigint>last_epoch
   ELSE epoch_row->'members' ? (driver->>'id') AND (epoch_row->>'guard'<>'nested_guard' OR driver->>'parentId' IS NOT NULL) END,'epoch_causality');
 END LOOP;
 PERFORM bootstrap_v3_assert(last_epoch=(frame->>'fence')::bigint,'fence_gap');RETURN frame;
END $$;

CREATE FUNCTION bootstrap_v3_lineage(ev JSONB) RETURNS TEXT LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE summary JSONB:='{}';field TEXT;value JSONB;hashes JSONB;record JSONB;total BIGINT:=0;BEGIN
 FOR field,value IN SELECT key,v FROM jsonb_each(ev) x(key,v) LOOP
  IF field IN ('mutations','receipts','epochs') THEN
   PERFORM bootstrap_v3_assert(jsonb_array_length(value)<=1024,'evidence_count');hashes:='[]';
   FOR record IN SELECT x FROM jsonb_array_elements(value) x LOOP
    total:=total+octet_length(bootstrap_proof_bytes(record,0));hashes:=hashes||jsonb_build_array(bootstrap_proof_digest(record));
   END LOOP;summary:=summary||jsonb_build_object(field,bootstrap_proof_digest(hashes));
  ELSE total:=total+octet_length(bootstrap_proof_bytes(value,0));summary:=summary||jsonb_build_object(field,bootstrap_proof_digest(value));END IF;
 END LOOP;
 PERFORM bootstrap_v3_assert(total<=1048576,'evidence_budget');
 RETURN bootstrap_proof_digest(jsonb_build_array('roost-bootstrap-v3-lineage-v1',ev->'anchorDigest',ev->'through',summary));
END $$;
CREATE FUNCTION bootstrap_v3_operation_guard() RETURNS TRIGGER LANGUAGE plpgsql AS $$
DECLARE before_frame JSONB;body JSONB;h JSONB;BEGIN
 PERFORM bootstrap_v3_assert(TG_OP='INSERT' AND pg_trigger_depth()=1,'operation_immutable');
 PERFORM bootstrap_v3_authorize(NEW.plan);before_frame:=bootstrap_v3_inventory(NEW.plan);
 SELECT value INTO h FROM jsonb_array_elements(before_frame->'heads') WHERE value->>'decisionId'=NEW.plan->'authority'->'attachment'->>'decisionId';
 PERFORM bootstrap_v3_assert(before_frame->>'sourceSetDigest'=NEW.plan->'authority'->>'sourceDigest'
  AND h->>'revision'=NEW.plan->'authority'->>'authorityRevision' AND h->>'digest'=NEW.plan->'authority'->>'authorityDigest' AND h->>'fanout'='true'
  AND NEW.id::text=NEW.plan->'command'->>'operationId' AND NEW.workspace_id::text=NEW.plan->'authority'->'attachment'->>'workspaceId'
  AND NEW.attachment_id::text=NEW.plan->'authority'->>'attachmentId','canonical_anchor');
 NEW.writer_xid:=pg_current_xact_id()::text;NEW.plan_digest:=bootstrap_proof_digest(NEW.plan);NEW.from_fence:=(before_frame->>'fence')::bigint;
 body:=jsonb_build_object('version','bootstrap-v3-projection-anchor-v1','operationId',NEW.id,'workspaceId',NEW.workspace_id,'writerXid',NEW.writer_xid,'planDigest',NEW.plan_digest,'before',before_frame);
 NEW.anchor:=body||jsonb_build_object('digest',bootstrap_proof_digest(jsonb_build_array('roost-bootstrap-v3-anchor-v1',body)));RETURN NEW;
END $$;
CREATE FUNCTION bootstrap_v3_own_guard() RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN NEW:=jsonb_populate_record(NEW,bootstrap_v3_guard(TG_TABLE_NAME,TG_OP,to_jsonb(NEW),to_jsonb(OLD)));RETURN NEW;END $$;
CREATE FUNCTION bootstrap_v3_own_audit() RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN PERFORM bootstrap_v3_capture(TG_TABLE_NAME,TG_OP,to_jsonb(NEW),to_jsonb(OLD));PERFORM bootstrap_v3_after(TG_TABLE_NAME,to_jsonb(NEW));RETURN NULL;END $$;
CREATE FUNCTION bootstrap_v3_immutable() RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'bootstrap_v3_immutable';END IF;
 PERFORM bootstrap_v3_assert(pg_trigger_depth()>1 AND current_setting('session_replication_role')='origin','automatic_native_evidence');RETURN NEW;
END $$;
CREATE FUNCTION bootstrap_v3_event_guard() RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN
 IF (CASE WHEN TG_OP='DELETE' THEN OLD.type ELSE NEW.type END) LIKE 'bootstrap.v3.%'
  OR TG_OP='UPDATE' AND OLD.type LIKE 'bootstrap.v3.%'
  OR EXISTS(SELECT 1 FROM bootstrap_v3_receipts WHERE event_id=CASE WHEN TG_OP='INSERT' THEN NEW.id ELSE OLD.id END)
  OR EXISTS(SELECT 1 FROM bootstrap_v3_epochs WHERE event_id=CASE WHEN TG_OP='INSERT' THEN NEW.id ELSE OLD.id END) THEN
  PERFORM bootstrap_v3_assert(TG_OP='INSERT' AND pg_trigger_depth()>1 AND current_setting('session_replication_role')='origin','native_event_immutable');
 END IF;IF TG_OP='DELETE' THEN RETURN OLD;END IF;RETURN NEW;
END $$;
CREATE FUNCTION bootstrap_v3_foreign_observe() RETURNS TRIGGER LANGUAGE plpgsql AS $$
DECLARE op UUID:=bootstrap_v3_active();v JSONB:=CASE WHEN TG_OP='DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END;f BIGINT;BEGIN
 -- Own root guards only admit the next exact row. Its pinned automatic audit
 -- has already captured it. Every other successful source write stays visible.
 IF op IS NOT NULL AND EXISTS(SELECT 1 FROM bootstrap_v3_mutations WHERE operation_id=op AND table_name=TG_TABLE_NAME
  AND after_digest=bootstrap_v3_native_digest(v) AND record IS NOT NULL) THEN RETURN NULL;END IF;
 SELECT revision INTO f FROM ready_source_fence WHERE id=1;
 INSERT INTO bootstrap_v3_mutations(operation_id,writer_xid,epoch,table_name,row_key,before_digest,after_digest,record)
 VALUES(NULL,pg_current_xact_id()::text,f,TG_TABLE_NAME,coalesce(v->>'id',v->>'decision_id',v->>'workspace_id','unknown')||coalesce(':'||(v->>'host_id'),''),
  CASE WHEN TG_OP<>'INSERT' THEN bootstrap_v3_native_digest(to_jsonb(OLD)) END,CASE WHEN TG_OP<>'DELETE' THEN bootstrap_v3_native_digest(to_jsonb(NEW)) END,NULL);
 RETURN NULL;
END $$;
CREATE FUNCTION bootstrap_v3_phase_guard() RETURNS TRIGGER LANGUAGE plpgsql AS $$
DECLARE o bootstrap_v3_operations;expected INT;ev JSONB;commitment JSONB;receipt JSONB;BEGIN
 PERFORM bootstrap_v3_assert(TG_OP='INSERT' AND pg_trigger_depth()=1,'phase_immutable');
 SELECT * INTO o FROM bootstrap_v3_operations WHERE id=NEW.operation_id;
 SELECT count(*)+1 INTO expected FROM bootstrap_v3_phases WHERE operation_id=o.id;
 PERFORM bootstrap_v3_assert(o.writer_xid=pg_current_xact_id()::text AND NEW.ordinal=expected AND NEW.ordinal BETWEEN 1 AND 6
  AND NEW.phase=(ARRAY['reservation','ticket','channel','attempt','link','seal'])[expected],'consecutive_phase');
 NEW.frame:=bootstrap_v3_check(o.id,NEW.phase);
 IF NEW.ordinal=6 THEN
  ev:=bootstrap_v3_evidence(o.id,'seal',NEW.frame);
  commitment:=jsonb_build_object('version','bootstrap-v3-projection-commitment-v1','operationId',o.id,'writerXid',o.writer_xid,'planDigest',o.plan_digest,'anchorDigest',o.anchor->'digest',
   'fromFence',o.from_fence::text,'toFence',NEW.frame->'fence','finalSourceSetDigest',NEW.frame->'sourceSetDigest','lineageDigest',bootstrap_v3_lineage(ev));
  receipt:=jsonb_build_object('version','bootstrap-proof-issuance-receipt-v3','domain','roost-bootstrap-proof-issuance-receipt-v3','operationId',o.id,
   'attachmentId',o.attachment_id,'ticketId',o.plan->'link'->'ticketId','attemptId',o.plan->'link'->'attemptId','planDigest',o.plan_digest,
   'envelopeDigest',o.plan->'link'->'ticketEnvelopeDigest','sealDigest',o.plan->'link'->'sealDigest','sourceDigest',o.plan->'authority'->'sourceDigest',
   'authorityRevision',o.plan->'authority'->'authorityRevision','authorityDigest',o.plan->'authority'->'authorityDigest','writerXid',o.writer_xid,
   'fromFence',o.from_fence::text,'toFence',NEW.frame->'fence','rowsDigest',NEW.frame->'sourceSetDigest','eventId',o.plan->'envelope'->'signed'->'payload'->'context'->'receiptEventId');
  INSERT INTO bootstrap_v3_commitments(operation_id,record,receipt) VALUES(o.id,commitment,receipt);
 END IF;RETURN NEW;
END $$;
CREATE FUNCTION bootstrap_v3_commit_guard() RETURNS TRIGGER LANGUAGE plpgsql AS $$
DECLARE frame JSONB;stored bootstrap_v3_phases;BEGIN
 SELECT * INTO stored FROM bootstrap_v3_phases WHERE operation_id=NEW.id AND ordinal=6;
 PERFORM bootstrap_v3_assert(stored.operation_id IS NOT NULL AND EXISTS(SELECT 1 FROM bootstrap_v3_commitments WHERE operation_id=NEW.id),'complete_operation_required');
 frame:=bootstrap_v3_check(NEW.id,'seal');PERFORM bootstrap_v3_assert(frame=stored.frame,'post_seal_drift');RETURN NULL;
END $$;

CREATE FUNCTION bootstrap_v3_write(p JSONB,requested_phase TEXT) RETURNS JSONB LANGUAGE plpgsql VOLATILE AS $$
DECLARE op UUID:=(p->'command'->>'operationId')::uuid;o bootstrap_v3_operations;ordinal INT;slot TEXT;BEGIN
 PERFORM bootstrap_v3_mode(true);PERFORM bootstrap_v3_catalog();
 ordinal:=array_position(ARRAY['reservation','ticket','channel','attempt','link','seal'],requested_phase);
 PERFORM bootstrap_v3_assert(ordinal IS NOT NULL AND pg_trigger_depth()=0,'phase_entry');
 IF ordinal=1 THEN
  INSERT INTO bootstrap_v3_operations(id,workspace_id,attachment_id,writer_xid,plan,plan_digest,anchor,from_fence)
  VALUES(op,(p->'authority'->'attachment'->>'workspaceId')::uuid,(p->'command'->>'attachmentId')::uuid,pg_current_xact_id()::text,p,'', '{}',1);
 ELSE
  SELECT * INTO o FROM bootstrap_v3_operations WHERE id=op;
  PERFORM bootstrap_v3_assert(o.writer_xid=pg_current_xact_id()::text AND o.plan=p AND o.plan_digest=bootstrap_proof_digest(p)
   AND (SELECT count(*) FROM bootstrap_v3_phases WHERE operation_id=op)=ordinal-1,'phase_plan_changed');
  PERFORM bootstrap_v3_assert(bootstrap_v3_check(op,(ARRAY['reservation','ticket','channel','attempt','link','seal'])[ordinal-1])=
   (SELECT frame FROM bootstrap_v3_phases WHERE operation_id=op AND bootstrap_v3_phases.ordinal=bootstrap_v3_write.ordinal-1),'phase_prefix_changed');
  CASE requested_phase
  WHEN 'ticket' THEN PERFORM bootstrap_v3_insert(op,'ticket');PERFORM bootstrap_v3_insert(op,'ticket-issue');
  WHEN 'channel' THEN PERFORM bootstrap_v3_insert(op,'channel-generation');PERFORM bootstrap_v3_insert(op,'channel-grant');PERFORM bootstrap_v3_insert(op,'channel-history');
  WHEN 'attempt' THEN PERFORM bootstrap_v3_insert(op,'attempt');PERFORM bootstrap_v3_insert(op,'attempt-history');PERFORM bootstrap_v3_insert(op,'ticket-consume');
  WHEN 'link' THEN PERFORM bootstrap_v3_insert(op,'proof-link');
  WHEN 'seal' THEN PERFORM bootstrap_v3_insert(op,'attempt-seal');
  ELSE RAISE EXCEPTION 'bootstrap_v3_phase';END CASE;
 END IF;
 INSERT INTO bootstrap_v3_phases(operation_id,ordinal,phase,frame) VALUES(op,ordinal,requested_phase,'{}');
 RETURN bootstrap_v3_read(op,requested_phase);
END $$;
CREATE FUNCTION bootstrap_v3_read(op UUID,through_phase TEXT) RETURNS JSONB LANGUAGE plpgsql VOLATILE AS $$
DECLARE o bootstrap_v3_operations;frame JSONB;ev JSONB;native_mutations JSONB;native_receipts JSONB;native_epochs JSONB;commitment JSONB;receipt JSONB;lo BIGINT;hi BIGINT;BEGIN
 PERFORM bootstrap_v3_mode(current_setting('transaction_read_only')='off');PERFORM bootstrap_v3_catalog();
 SELECT * INTO o FROM bootstrap_v3_operations WHERE id=op;
 IF o.id IS NULL THEN RETURN NULL;END IF;
 SELECT p.frame INTO frame FROM bootstrap_v3_phases p WHERE operation_id=op AND phase=through_phase;
 PERFORM bootstrap_v3_assert(frame IS NOT NULL,'phase_not_recorded');
 IF current_setting('transaction_read_only')='off' THEN
  PERFORM bootstrap_v3_assert(o.writer_xid=pg_current_xact_id()::text AND frame=bootstrap_v3_check(op,through_phase),'writer_readback');
 END IF;
 ev:=bootstrap_v3_evidence(op,through_phase,frame);lo:=o.from_fence;hi:=(frame->>'fence')::bigint;
 SELECT coalesce(jsonb_agg(to_jsonb(m) ORDER BY sequence),'[]') INTO native_mutations FROM bootstrap_v3_mutations m WHERE epoch>lo AND epoch<=hi;
 SELECT coalesce(jsonb_agg(jsonb_build_object('mapping',to_jsonb(r),'receipt',bootstrap_v3_native_receipt(r),'event',to_jsonb(e)) ORDER BY r.id),'[]') INTO native_receipts
 FROM bootstrap_v3_receipts r JOIN bootstrap_v3_mutations m ON m.sequence=r.mutation_sequence JOIN events e ON e.id=r.event_id WHERE m.epoch>lo AND m.epoch<=hi;
 SELECT coalesce(jsonb_agg(jsonb_build_object('receipt',to_jsonb(f),'claim',to_jsonb(c),'event',to_jsonb(e)) ORDER BY f.revision),'[]') INTO native_epochs
 FROM bootstrap_v3_epochs f LEFT JOIN bootstrap_v3_epoch_claims c ON c.revision=f.revision JOIN events e ON e.id=f.event_id WHERE f.revision>lo AND f.revision<=hi;
 SELECT x.record,x.receipt INTO commitment,receipt FROM bootstrap_v3_commitments x WHERE operation_id=op;
 IF through_phase='seal' THEN
  PERFORM bootstrap_v3_assert(commitment->>'lineageDigest'=bootstrap_v3_lineage(ev) AND commitment->'finalSourceSetDigest'=frame->'sourceSetDigest','committed_lineage');
 END IF;
 RETURN jsonb_build_object('version','bootstrap-v3-native-packet-v1','plan',o.plan,'anchor',o.anchor,'evidence',ev,
  'native',jsonb_build_object('mutations',native_mutations,'receipts',native_receipts,'epochs',native_epochs,'unfilteredReceipts',bootstrap_v3_interval_receipts(lo,hi)),'commitment',commitment,'receipt',receipt,
  'persistenceQualified',false,'cryptographyQualified',false,'sendPermit',false,'implementationReady',false,'executionSupported',false,'pilotReady',false,
  'liveAdmissionAllowed',false,'pilotExecutionAuthorized',false,'pilotExecutionStarted',false,'transportQualified',false,'launchAuthority',false);
END $$;

CREATE FUNCTION bootstrap_v3_interval_receipts(lo BIGINT,hi BIGINT) RETURNS JSONB LANGUAGE plpgsql VOLATILE AS $$
DECLARE result JSONB;BEGIN
 -- Include legacy receipts too. A foreign/unknown writer never disappears just
 -- because it has no v3 mapping. The envelope exposes complete public receipts
 -- and their Events; secret-bearing source rows are hashed in inventory SQL.
 WITH observed(native_table,receipt,event) AS (
 SELECT 'worker_bootstrap_write_receipts',to_jsonb(r),to_jsonb(e) FROM worker_bootstrap_write_receipts r LEFT JOIN events e ON e.id=r.event_id WHERE r.fence_revision>lo AND r.fence_revision<=hi
 UNION ALL SELECT 'decision_attestation_write_receipts',to_jsonb(r),to_jsonb(e) FROM decision_attestation_write_receipts r LEFT JOIN events e ON e.id=r.event_id WHERE r.fence_revision>lo AND r.fence_revision<=hi
 UNION ALL SELECT 'worker_transport_write_audit',to_jsonb(r),to_jsonb(e) FROM worker_transport_write_audit r
  LEFT JOIN bootstrap_v3_mutations m ON m.table_name=r.table_name AND m.writer_xid=r.writer_xid AND m.after_digest=r.row_digest AND m.epoch=r.fence_revision
  LEFT JOIN bootstrap_v3_receipts link ON link.mutation_sequence=m.sequence AND link.family='transport' LEFT JOIN events e ON e.id=link.event_id
  WHERE r.fence_revision>lo AND r.fence_revision<=hi
 UNION ALL SELECT 'bootstrap_proof_write_receipts',to_jsonb(r),to_jsonb(e) FROM bootstrap_proof_write_receipts r LEFT JOIN events e ON e.id=r.event_id WHERE r.to_fence>lo AND r.to_fence<=hi
 ) SELECT coalesce(jsonb_agg(jsonb_build_object('table',native_table,'receipt',receipt,'event',event) ORDER BY native_table,receipt::text),'[]') INTO result FROM observed;
 PERFORM bootstrap_v3_assert(jsonb_array_length(result)<=1024,'native_receipt_budget');RETURN result;
END $$;

CREATE FUNCTION bootstrap_v3_catalog() RETURNS BOOLEAN LANGUAGE plpgsql VOLATILE AS $$
DECLARE manifest JSONB;expected JSONB;actual JSONB;n INT;BEGIN
 SELECT record INTO manifest FROM bootstrap_v3_catalog_manifest WHERE id;
 PERFORM bootstrap_v3_assert(manifest IS NOT NULL AND (SELECT count(*) FROM bootstrap_v3_catalog_manifest)=1,'catalog_manifest');
 FOR expected IN SELECT value FROM jsonb_array_elements(manifest->'functions') LOOP
  SELECT count(*),jsonb_agg(jsonb_build_object('name',p.proname,'args',pg_get_function_identity_arguments(p.oid),'result',p.prorettype::regtype::text,
   'language',l.lanname,'volatility',p.provolatile::text,'defaults',pg_get_expr(p.proargdefaults,0),'hash',encode(sha256(convert_to(replace(p.prosrc,chr(13),''),'UTF8')),'hex'),
   'enabled',nsp.nspname='public' AND p.prokind='f' AND NOT p.prosecdef AND p.proconfig IS NULL AND NOT p.proisstrict AND NOT p.proleakproof AND p.proparallel='u'))
  INTO n,actual FROM pg_proc p JOIN pg_namespace nsp ON nsp.oid=p.pronamespace JOIN pg_language l ON l.oid=p.prolang WHERE p.proname=expected->>'name';
  PERFORM bootstrap_v3_assert(n=1 AND actual->0=expected||jsonb_build_object('enabled',true),'function_catalog');
 END LOOP;
 FOR expected IN SELECT value FROM jsonb_array_elements(manifest->'triggers') LOOP
  SELECT count(*),jsonb_agg(jsonb_build_object('table',c.relname,'name',t.tgname,'function',p.proname,'kind',t.tgtype::int,'deferred',t.tgdeferrable,
   'enabled',t.tgenabled='O' AND t.tgqual IS NULL AND t.tgnargs=0 AND t.tgattr=''::int2vector AND NOT t.tgisinternal
    AND (t.tgconstraint<>0)=t.tgdeferrable AND t.tginitdeferred=t.tgdeferrable AND ns.nspname='public' AND pn.nspname='public'
    AND c.relkind='r' AND p.pronargs=0 AND p.prorettype='trigger'::regtype))
  INTO n,actual FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace ns ON ns.oid=c.relnamespace
  JOIN pg_proc p ON p.oid=t.tgfoid JOIN pg_namespace pn ON pn.oid=p.pronamespace
  WHERE c.relname=expected->>'table' AND t.tgname=expected->>'name';
  PERFORM bootstrap_v3_assert(n=1 AND actual->0=expected||jsonb_build_object('enabled',true),'trigger_catalog');
 END LOOP;
 -- Extra source triggers can change ordering or manufacture audit evidence.
 PERFORM bootstrap_v3_assert(NOT EXISTS(SELECT 1 FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace ns ON ns.oid=c.relnamespace
  WHERE ns.nspname='public' AND NOT t.tgisinternal AND c.relname IN (SELECT jsonb_array_elements_text(manifest->'exactTriggerTables'))
  AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(manifest->'triggers') x WHERE x->>'table'=c.relname AND x->>'name'=t.tgname)),'extra_source_trigger');
 FOR expected IN SELECT value FROM jsonb_array_elements(manifest->'columns') LOOP
  SELECT jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'generated',a.attgenerated::text) ORDER BY a.attnum) INTO actual
  FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace ns ON ns.oid=c.relnamespace
  WHERE ns.nspname='public' AND c.relname=expected->>'table' AND a.attnum>0 AND NOT a.attisdropped AND c.relkind='r';
  PERFORM bootstrap_v3_assert(actual=expected->'columns','writer_schema');
 END LOOP;
 FOR expected IN SELECT value FROM jsonb_array_elements(manifest->'foreignKeys') LOOP
  SELECT count(*) INTO n FROM pg_constraint c JOIN pg_class child ON child.oid=c.conrelid JOIN pg_namespace cn ON cn.oid=child.relnamespace
   JOIN pg_class parent ON parent.oid=c.confrelid JOIN pg_namespace pn ON pn.oid=parent.relnamespace
  WHERE c.contype='f' AND cn.nspname='public' AND pn.nspname='public' AND child.relname=expected->>'table' AND parent.relname=expected->>'target'
   AND c.convalidated AND NOT c.condeferrable AND NOT c.condeferred AND c.confdeltype='r' AND c.confupdtype='a' AND c.confmatchtype='s'
   AND to_jsonb(ARRAY(SELECT a.attname FROM unnest(c.conkey) WITH ORDINALITY k(num,ord) JOIN pg_attribute a ON a.attrelid=c.conrelid AND a.attnum=k.num ORDER BY k.ord))=expected->'columns'
   AND to_jsonb(ARRAY(SELECT a.attname FROM unnest(c.confkey) WITH ORDINALITY k(num,ord) JOIN pg_attribute a ON a.attrelid=c.confrelid AND a.attnum=k.num ORDER BY k.ord))=expected->'targetColumns';
  PERFORM bootstrap_v3_assert(n=1,'foreign_key_catalog');
 END LOOP;
 RETURN true;
END $$;

