 WHERE n.nspname='public' AND p.proname='transport_bootstrap_advance' AND p.pronargs=0 AND p.prorettype='trigger'::regtype
 AND p.prolang=(SELECT oid FROM pg_language WHERE lanname='plpgsql') AND NOT p.prosecdef AND p.proconfig IS NULL;
 IF body IS NULL OR encode(sha256(convert_to(body,'UTF8')),'hex')<>'098c585bc0ff2e67f4f7de330c0da524d3cf5fb8ea1ae0d3684bd81a15f3c17f' THEN RAISE EXCEPTION 'bootstrap_v3_old_guard_drift';END IF;
 body:=substring(body FROM 1 FOR position('BEGIN' IN body)+4)||chr(10)||' '||prefix||chr(10)||substring(body FROM position('BEGIN' IN body)+5);
 EXECUTE 'CREATE OR REPLACE FUNCTION transport_bootstrap_advance() RETURNS TRIGGER LANGUAGE plpgsql AS '||quote_literal(body);
END $upgrade$;
DO $upgrade$ DECLARE body TEXT;prefix TEXT:='IF bootstrap_v3_active() IS NOT NULL AND TG_TABLE_NAME IN (''worker_bootstrap_tickets'',''worker_bootstrap_attempts'',''worker_bootstrap_history'',''worker_bootstrap_heads'',''worker_bootstrap_audit'',''worker_bootstrap_lifecycle_events'',''worker_transport_generations'',''worker_transport_bootstrap_grants'',''worker_transport_history'',''worker_transport_heads'',''decision_authority_events'') THEN
 IF TG_TABLE_NAME=''decision_authority_events'' THEN PERFORM bootstrap_v3_capture(TG_TABLE_NAME,TG_OP,to_jsonb(NEW),to_jsonb(OLD));END IF;
 PERFORM bootstrap_v3_after(TG_TABLE_NAME,to_jsonb(NEW));RETURN NULL;END IF;';BEGIN
 SELECT replace(p.prosrc,chr(13),'') INTO body FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
 WHERE n.nspname='public' AND p.proname='decision_attestation_audit' AND p.pronargs=0 AND p.prorettype='trigger'::regtype
 AND p.prolang=(SELECT oid FROM pg_language WHERE lanname='plpgsql') AND NOT p.prosecdef AND p.proconfig IS NULL;
 IF body IS NULL OR encode(sha256(convert_to(body,'UTF8')),'hex')<>'524ae686d6d97955e3fee6f97cc2e91918ac8817e2119d2e4e712a18972f943b' THEN RAISE EXCEPTION 'bootstrap_v3_old_guard_drift';END IF;
 body:=substring(body FROM 1 FOR position('BEGIN' IN body)+4)||chr(10)||' '||prefix||chr(10)||substring(body FROM position('BEGIN' IN body)+5);
 EXECUTE 'CREATE OR REPLACE FUNCTION decision_attestation_audit() RETURNS TRIGGER LANGUAGE plpgsql AS '||quote_literal(body);
END $upgrade$;
DO $upgrade$ DECLARE body TEXT;prefix TEXT:='IF bootstrap_v3_active() IS NOT NULL AND TG_TABLE_NAME=''worker_bootstrap_tickets'' THEN PERFORM bootstrap_v3_advance(bootstrap_v3_active(),bootstrap_v3_next(bootstrap_v3_active())->>''slot'',''statement_guard'');RETURN NULL;END IF;';BEGIN
 SELECT replace(p.prosrc,chr(13),'') INTO body FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
 WHERE n.nspname='public' AND p.proname='transport_bootstrap_source_lock' AND p.pronargs=0 AND p.prorettype='trigger'::regtype
 AND p.prolang=(SELECT oid FROM pg_language WHERE lanname='plpgsql') AND NOT p.prosecdef AND p.proconfig IS NULL;
 IF body IS NULL OR encode(sha256(convert_to(body,'UTF8')),'hex')<>'c4115545454b641c20aa355e713f03bb3534a6506d4faef93e4a5209ad3a5510' THEN RAISE EXCEPTION 'bootstrap_v3_old_guard_drift';END IF;
 body:=substring(body FROM 1 FOR position('BEGIN' IN body)+4)||chr(10)||' '||prefix||chr(10)||substring(body FROM position('BEGIN' IN body)+5);
 EXECUTE 'CREATE OR REPLACE FUNCTION transport_bootstrap_source_lock() RETURNS TRIGGER LANGUAGE plpgsql AS '||quote_literal(body);
END $upgrade$;
DO $upgrade$ DECLARE body TEXT;prefix TEXT:='IF bootstrap_v3_active() IS NOT NULL AND TG_TABLE_NAME=''decision_authority_events'' THEN PERFORM bootstrap_v3_mode(true);RETURN NULL;END IF;';BEGIN
 SELECT replace(p.prosrc,chr(13),'') INTO body FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
 WHERE n.nspname='public' AND p.proname='decision_attestation_lock' AND p.pronargs=0 AND p.prorettype='trigger'::regtype
 AND p.prolang=(SELECT oid FROM pg_language WHERE lanname='plpgsql') AND NOT p.prosecdef AND p.proconfig IS NULL;
 IF body IS NULL OR encode(sha256(convert_to(body,'UTF8')),'hex')<>'3316c5fbc4af10d15f83bde791aa7cf578f94875e224f8b7e35904099c44bee1' THEN RAISE EXCEPTION 'bootstrap_v3_old_guard_drift';END IF;
 body:=substring(body FROM 1 FOR position('BEGIN' IN body)+4)||chr(10)||' '||prefix||chr(10)||substring(body FROM position('BEGIN' IN body)+5);
 EXECUTE 'CREATE OR REPLACE FUNCTION decision_attestation_lock() RETURNS TRIGGER LANGUAGE plpgsql AS '||quote_literal(body);
END $upgrade$;
